// n8n Code node: Resolve Reporting Period
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Resolve Reporting Period                (Run Once for ALL Items)
//
// The single place in the workflow that decides WHAT WINDOW WE ARE
// REPORTING ON. Every downstream node reads the window from here and
// never computes a date of its own. One definition, one place to fix.
//
// Three triggers land on this node and they arrive in different shapes:
//   - Webhook          POST body { period, start, end, force, reference_date }
//   - Schedule Trigger no body at all -> default period
//   - Manual Trigger   no body at all -> default period
//
// THE REFERENCE DATE IS NOT new Date().
// The three sources cover Jan 2025 - Jun 2026. Anchoring to the real
// clock makes every window empty and the dashboard look broken while the
// workflow is behaving perfectly. So the anchor is an explicit input:
//   1. webhook body.reference_date      (per-run override, used in the demo)
//   2. IKE_KOYA_REFERENCE_DATE          (deployment default - see setting())
//   3. today                            (only if neither is set)
//
// WHERE A SETTING COMES FROM, AND WHY THERE ARE TWO PLACES
// n8n exposes deployment configuration through two different objects and
// which one works depends on how the instance is hosted:
//
//   $vars   n8n Cloud - Settings -> Variables. The only one available on
//           Cloud, because Cloud does not run on a machine whose process
//           environment you control.
//   $env    self-hosted - the process environment. BLOCKED on Cloud
//           (N8N_BLOCK_ENV_ACCESS_IN_NODE), where reading it THROWS rather
//           than returning undefined.
//
// Reading only $env is what produced "Invalid URL: /rest/v1/rpc/..." on a
// Cloud run: the read threw, the catch returned '', the URL expression
// evaluated to just the path, and the HTTP node reported a malformed URL
// rather than a missing setting. setting() reads both, in that order, and
// every read is wrapped - the catch means "not configured here", never
// "crash the run".
//
// THERE IS NO HARDCODED DATE IN THIS FILE, and no hardcoded project URL
// either. Both are configuration, and configuration baked into a Code node
// is configuration nobody rotates: it ships in the exported JSON, it is
// invisible to whoever changes the env var and wonders why nothing moved,
// and it rots silently the day the dataset moves on. An unset anchor is a
// CONFIGURATION ERROR - the run falls through to the real clock and says so
// loudly in period_warnings, rather than quietly pretending it is June 2026.
//
// Set IKE_KOYA_REFERENCE_DATE=2026-06-30 while the sources are the sample
// dataset, and IKE_KOYA_REFERENCE_DATE=today on the day they go live.
// ============================================================

const DEFAULT_PERIOD = 'last_30d';
const SUPPORTED = ['last_7d', 'last_30d', 'last_90d', 'ytd', 'custom'];

// The host that appears in place of the project URL when nothing is
// configured. It is deliberately a real-looking URL on the reserved
// .invalid TLD rather than an empty string: an empty one turns
// "{{ supabase_url }}/rest/v1/rpc/publish_report" into a bare path, and n8n
// reports that as "Invalid URL", which sends the reader looking at the HTTP
// node instead of at the setting that is actually missing. This fails at
// DNS instead, naming itself in the error.
const UNSET_URL = 'https://IKE-SUPABASE-URL-IS-NOT-SET.invalid';

// ---- deployment settings ------------------------------------
// $vars first (n8n Cloud), then $env (self-hosted). Both reads are guarded:
// on Cloud, touching $env throws.
function setting(name) {
  try {
    const v = (typeof $vars !== 'undefined' && $vars) ? $vars[name] : undefined;
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return { value: String(v).trim(), source: 'vars' };
    }
  } catch (e) { /* no Variables on this instance */ }

  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[name] : undefined;
    if (v !== undefined && v !== null && String(v).trim() !== '') {
      return { value: String(v).trim(), source: 'env' };
    }
  } catch (e) { /* env access blocked, which is the Cloud default */ }

  return { value: '', source: null };
}

// ---- date helpers -------------------------------------------
// Everything is handled as a plain YYYY-MM-DD string in UTC. No local
// timezone ever touches these values: an n8n instance in Lagos and one in
// London must produce byte-identical windows, or the same period gets two
// different run_ids and the dashboard shows two "latest" runs.
const ISO = /^\d{4}-\d{2}-\d{2}$/;

function isValidISODate(s) {
  if (typeof s !== 'string' || !ISO.test(s)) return false;
  // Rejects 2026-02-30: Date rolls it to March 2, so the round trip fails.
  const d = new Date(s + 'T00:00:00Z');
  if (Number.isNaN(d.getTime())) return false;
  return d.toISOString().slice(0, 10) === s;
}

function toUTC(s) { return new Date(s + 'T00:00:00Z'); }
function fmt(d) { return d.toISOString().slice(0, 10); }
function addDays(s, n) {
  const d = toUTC(s);
  d.setUTCDate(d.getUTCDate() + n);
  return fmt(d);
}
function daysBetween(a, b) {
  return Math.round((toUTC(b).getTime() - toUTC(a).getTime()) / 86400000);
}

// ---- gather the trigger payload -----------------------------
// Any of the three triggers may be the one that fired. Read defensively:
// a Schedule Trigger item is {timestamp, ...} with no body at all.
const first = ($input.all()[0] && $input.all()[0].json) || {};
const body = (first.body && typeof first.body === 'object') ? first.body : first;
const query = (first.query && typeof first.query === 'object') ? first.query : {};
const req = Object.assign({}, query, body); // body wins over querystring

const warnings = [];

// ---- 1. reference date --------------------------------------
function resolveReferenceDate() {
  const fromRequest = String(req.reference_date || '').trim();
  if (fromRequest) {
    if (isValidISODate(fromRequest)) return { value: fromRequest, source: 'request' };
    warnings.push({
      code: 'INVALID_REFERENCE_DATE',
      severity: 'warning',
      message: 'reference_date "' + fromRequest + '" is not a valid YYYY-MM-DD date. Falling back to the configured anchor.',
    });
  }

  const configured = setting('IKE_KOYA_REFERENCE_DATE');
  const fromEnv = configured.value;

  if (fromEnv) {
    // 'today' is an explicit, supported value: set IKE_KOYA_REFERENCE_DATE=today
    // on the day the sources go live and this file needs no edit. Checked
    // BEFORE the ISO test, or it fails validation and reports itself as a
    // bad date on the way to doing exactly the right thing.
    if (fromEnv.toLowerCase() === 'today') {
      return { value: new Date().toISOString().slice(0, 10), source: 'clock' };
    }
    if (isValidISODate(fromEnv)) return { value: fromEnv, source: configured.source };
    warnings.push({
      code: 'INVALID_REFERENCE_DATE',
      severity: 'error',
      message: 'IKE_KOYA_REFERENCE_DATE "' + fromEnv + '" (read from ' + (configured.source === 'vars' ? 'n8n Variables' : 'the instance environment') + ') is neither a YYYY-MM-DD date nor "today". Anchoring to the real clock instead, which will return an empty window while the sources end before today.',
    });
    return { value: new Date().toISOString().slice(0, 10), source: 'clock_after_invalid_env' };
  }

  // Nothing configured. The clock is the only honest answer left, and it is
  // very probably the wrong one, so this is an error rather than a shrug.
  warnings.push({
    code: 'REFERENCE_DATE_NOT_SET',
    severity: 'error',
    message: 'IKE_KOYA_REFERENCE_DATE is not set, so the report is anchored to today. Set it in n8n under Settings -> Variables (n8n Cloud) or in the instance environment (self-hosted). If the sources end before today every window will be empty and the dashboard will look broken while the workflow is behaving correctly. Use the dataset horizon while the sample data is the source, or "today" once the sources are live.',
  });
  return { value: new Date().toISOString().slice(0, 10), source: 'clock_unset' };
}

const ref = resolveReferenceDate();
const referenceDate = ref.value;

// ---- 2. period key ------------------------------------------
let periodKey = String(req.period || req.period_key || '').trim().toLowerCase();
if (periodKey === '') {
  periodKey = DEFAULT_PERIOD;
} else if (SUPPORTED.indexOf(periodKey) === -1) {
  warnings.push({
    code: 'UNKNOWN_PERIOD',
    severity: 'warning',
    message: 'Unknown period "' + periodKey + '". Supported: ' + SUPPORTED.join(', ') + '. Defaulted to ' + DEFAULT_PERIOD + '.',
  });
  periodKey = DEFAULT_PERIOD;
}

// ---- 3. window ----------------------------------------------
// Windows are INCLUSIVE of both endpoints and match the KPI guide exactly:
//   last  7 days -> 23 Jun - 30 Jun 2026   (end minus 7 days)
//   last 30 days -> 31 May - 30 Jun 2026   (end minus 30 days)
//   last 90 days ->  1 Apr - 30 Jun 2026   (end minus 90 days)
//   year to date ->  1 Jan - 30 Jun 2026
// The guide's own worked examples are the spec. A "30 day" window that is
// inclusive on both ends spans 31 dates; that is intentional and is stated
// on the dashboard so nobody reconciles a count and finds it one off.
let start;
let end;
let label;

if (periodKey === 'custom') {
  const cs = String(req.start || '').trim();
  const ce = String(req.end || '').trim();
  const badStart = !isValidISODate(cs);
  const badEnd = !isValidISODate(ce);

  if (badStart || badEnd) {
    warnings.push({
      code: 'INVALID_CUSTOM_RANGE',
      severity: 'warning',
      message: 'Custom range needs valid start and end dates (YYYY-MM-DD). Got start="' + cs + '", end="' + ce + '". Fell back to ' + DEFAULT_PERIOD + '.',
    });
    periodKey = DEFAULT_PERIOD;
  } else if (daysBetween(cs, ce) < 0) {
    // Swap rather than fail. A reversed range is a user slip, not a reason
    // to deny leadership a report, but it is recorded so it is visible.
    warnings.push({
      code: 'REVERSED_CUSTOM_RANGE',
      severity: 'warning',
      message: 'Custom range start (' + cs + ') was after end (' + ce + '). The two were swapped.',
    });
    start = ce; end = cs;
  } else {
    start = cs; end = ce;
  }

  if (start && end) {
    label = 'Custom: ' + start + ' to ' + end;
    if (daysBetween(start, end) > 1095) {
      warnings.push({
        code: 'VERY_WIDE_RANGE',
        severity: 'info',
        message: 'Custom range spans ' + (daysBetween(start, end) + 1) + ' days. Trend comparisons over windows this wide are weak.',
      });
    }
  }
}

if (!start) {
  end = referenceDate;
  if (periodKey === 'last_7d') { start = addDays(end, -7); label = 'Last 7 days'; }
  else if (periodKey === 'last_30d') { start = addDays(end, -30); label = 'Last 30 days'; }
  else if (periodKey === 'last_90d') { start = addDays(end, -90); label = 'Last 90 days'; }
  else if (periodKey === 'ytd') { start = end.slice(0, 4) + '-01-01'; label = 'Year to date'; }
}

const spanDays = daysBetween(start, end) + 1;

// ---- 4. the comparison window -------------------------------
// The KPI guide asks Claude whether win rate "improved, declined, or stayed
// stable" and whether time to hire is rising. Neither question can be
// answered from one window of numbers. So every run computes a second,
// comparable window and hands Claude both. Without this the model has to
// guess at a direction, and a guessed trend reads exactly like a real one.
//
//   rolling windows -> the equal-length window immediately before
//   year to date    -> the SAME calendar span one year earlier, because
//                      "1 Jan - 30 Jun vs the preceding 181 days of last
//                      year" compares a half year to a different half year
//                      and the seasonality makes it meaningless
let compareStart;
let compareEnd;
let compareLabel;

if (periodKey === 'ytd') {
  const priorYear = String(Number(end.slice(0, 4)) - 1);
  compareStart = priorYear + '-01-01';
  compareEnd = priorYear + end.slice(4);
  if (!isValidISODate(compareEnd)) compareEnd = priorYear + '-02-28'; // 29 Feb -> 28 Feb
  compareLabel = 'Same period ' + priorYear;
} else {
  compareEnd = addDays(start, -1);
  compareStart = addDays(compareEnd, -(spanDays - 1));
  compareLabel = 'Preceding ' + spanDays + ' days';
}

// ---- 5. run identity ----------------------------------------
// run_id is DETERMINISTIC and derived only from the window. Re-running the
// same period upserts the same row instead of appending a new one, which is
// what makes the whole workflow safe to run twice. Nothing random, no
// timestamp, no execution id in the key.
const runId = ['run', periodKey, start, end, referenceDate].join('_').replace(/[^a-zA-Z0-9_\-]/g, '');

const force = req.force === true || String(req.force || '').toLowerCase() === 'true';

// ---- 6. Supabase base URL -----------------------------------
// Resolved once, here, so every write node reads it from one place.
// Configuration only - there is no literal to fall back to. A project URL is
// not a secret (the browser is served it in dashboard/config.js), but it IS a
// project identifier, and hardcoding it means the exported workflow points
// at one specific Supabase project forever. The KEY is a different matter
// entirely and lives in n8n's credential store, never in this workflow, the
// exported JSON, or the browser.
const supabaseSetting = setting('IKE_SUPABASE_URL');
let supabaseUrl = supabaseSetting.value.replace(/\/+$/, '');
let supabaseUrlConfigured = Boolean(supabaseUrl);

if (supabaseUrl && !/^https:\/\//.test(supabaseUrl)) {
  // A URL without a scheme fails the same way an absent one does - as a
  // malformed URL in an HTTP node, three nodes downstream of the mistake.
  warnings.push({
    code: 'SUPABASE_URL_NOT_SET',
    severity: 'error',
    message: 'IKE_SUPABASE_URL is "' + supabaseUrl + '", which does not start with https://. It must be the full project URL, e.g. https://YOUR-PROJECT-REF.supabase.co. Every Supabase write will fail until this is fixed.',
  });
  supabaseUrl = '';
  supabaseUrlConfigured = false;
}

if (!supabaseUrlConfigured) {
  // Substituted rather than left empty: see UNSET_URL above. The write still
  // fails - it has to, there is nowhere to write - but it fails saying what
  // is missing instead of "Invalid URL".
  supabaseUrl = UNSET_URL;
  warnings.push({
    code: 'SUPABASE_URL_NOT_SET',
    severity: 'error',
    message: 'IKE_SUPABASE_URL is not set, so there is nowhere to publish this report. ' +
      'On n8n Cloud add it under Settings -> Variables; self-hosted, add it to the instance ' +
      'environment. The value is the Supabase project URL, e.g. https://YOUR-PROJECT-REF.supabase.co ' +
      '- Project Settings -> Data API. Every Supabase write will fail until this is done.',
  });
}

// Where the report can legitimately be empty, say so up front rather than
// letting an empty dashboard read as a broken one.
if (daysBetween(referenceDate, start) > 0) {
  warnings.push({
    code: 'WINDOW_AFTER_REFERENCE',
    severity: 'warning',
    message: 'The window starts (' + start + ') after the reference date (' + referenceDate + '). Expect no records.',
  });
}

return [{
  json: {
    run_id: runId,
    period_key: periodKey,
    period_label: label,
    period_start: start,
    period_end: end,
    period_days: spanDays,
    compare_start: compareStart,
    compare_end: compareEnd,
    compare_label: compareLabel,
    reference_date: referenceDate,
    reference_date_source: ref.source,
    // Which of $vars / $env each setting was found in, so a run that used
    // the wrong one can be diagnosed from its output rather than by guessing.
    config_source: {
      reference_date: ref.source,
      supabase_url: supabaseSetting.source,
    },
    supabase_url_configured: supabaseUrlConfigured,
    force_refresh: force,
    supabase_url: supabaseUrl,
    requested_by: String(req.requested_by || '').slice(0, 120) || 'scheduled',
    triggered_at: new Date().toISOString(),
    period_warnings: warnings,
  },
}];

// n8n Code node: Normalize Sales
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Normalize Sales (Google Sheets)         (Run Once for ALL Items)
//
// Turns whatever the Sheets node hands back into typed, canonical records
// plus an explicit list of everything wrong with them.
//
// TWO RULES THIS NODE NEVER BREAKS:
//
// 1. A BAD RECORD IS NEVER SILENTLY DROPPED. It is kept, marked
//    usable_for_period = false, and the reason is attached to it. The
//    metrics node then decides, metric by metric, whether it can be used.
//    Deleting the row here would make the count quietly wrong and nobody
//    would ever know which rows went missing.
//
// 2. A MISSING NUMBER IS null, NEVER 0. "Closed Won with no amount" and
//    "Closed Won for nothing" are different facts. Coercing blank to zero
//    silently understates revenue and there is no way to detect it later.
//
// 3. EVERY ISSUE CARRIES THE DATES OF THE RECORD IT CAME FROM, in
//    `record_dates`. Without them the dashboard's data quality panel is a
//    list about the whole spreadsheet shown under a heading that says
//    "Last 30 days" - warnings about leads from March sitting under a June
//    report, inflating the warning badge for records the numbers above
//    never touched. Compute Metrics uses these dates to decide which
//    issues belong to the selected window. An issue with no dates at all
//    (a source outage, an undated row) belongs to every window, and is
//    marked as such rather than silently dropped.
//
// THE marketing_spend TRAP
// ------------------------
// marketing_spend is NOT a per-lead cost. The source carries ONE budget
// figure per calendar month, repeated on every row of that month. Summing
// the column over the full history gives 291,800 against a true spend of
// 33,500 - inflated 8.7x, and cost per lead inflated with it. So this node
// only tags each row with its month; the metrics node collapses month to a
// single figure. See computeMarketingSpend() in Compute Metrics.
// ============================================================

const ISO = /^\d{4}-\d{2}-\d{2}$/;

// Canonical status vocabulary. The source is clean today; a hand-edited
// sheet will not be, so accept the obvious variants rather than dropping
// a real deal over a lowercase 'w'.
const STATUS_MAP = {
  'closed won': 'Closed Won', 'closedwon': 'Closed Won', 'won': 'Closed Won',
  'closed lost': 'Closed Lost', 'closedlost': 'Closed Lost', 'lost': 'Closed Lost',
  'qualified': 'Qualified',
  'proposal sent': 'Proposal Sent', 'proposal': 'Proposal Sent',
};

function isValidISODate(s) {
  if (typeof s !== 'string' || !ISO.test(s)) return false;
  const d = new Date(s + 'T00:00:00Z');
  if (Number.isNaN(d.getTime())) return false;
  return d.toISOString().slice(0, 10) === s; // rejects 2026-02-30
}

// Accepts a bare number, "3,500", "$3,500.00", " 3500 ". Returns null for
// anything it cannot read - including the empty string. Never returns 0
// unless the source genuinely said zero.
function num(v) {
  if (v === null || v === undefined) return null;
  const raw = String(v).trim();
  if (raw === '') return null;
  const cleaned = raw.replace(/[^0-9.\-]/g, '');
  if (cleaned === '' || cleaned === '-' || cleaned === '.') return null;
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : null;
}

function str(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

// Sheets and Airtable both hand back column names with whatever casing and
// spacing the header row happens to have. Read through a normalised map so
// a renamed "Deal Amount" does not become a silent null.
function field(row, names) {
  const keys = Object.keys(row);
  const norm = {};
  for (const k of keys) norm[k.toLowerCase().replace(/[\s_\-]/g, '')] = row[k];
  for (const n of names) {
    const key = n.toLowerCase().replace(/[\s_\-]/g, '');
    if (norm[key] !== undefined) return norm[key];
  }
  return undefined;
}

const rows = $input.all();
const out = [];
const issues = [];
const seenLeadIds = new Set();

let index = 0;
for (const item of rows) {
  const row = item.json || {};
  index += 1;

  // The Sheets node with onError=continue emits an error item rather than
  // throwing. That is a source failure, not a data problem - it must not be
  // mistaken for "the sheet was empty".
  if (row.error) {
    issues.push({
      source: 'sales', severity: 'error', code: 'SOURCE_ERROR',
      record_id: null,
      message: 'Google Sheets returned an error: ' + String(row.error).slice(0, 200),
    });
    continue;
  }

  const leadId = str(field(row, ['lead_id', 'leadid', 'id']));
  const rawDate = str(field(row, ['date', 'lead_date', 'created_date']));
  const rawStatus = str(field(row, ['status', 'deal_status', 'stage']));
  const rawAmount = field(row, ['deal_amount', 'amount', 'value']);
  const rawSpend = field(row, ['marketing_spend', 'spend']);
  const rawSource = str(field(row, ['lead_source', 'source', 'channel']));

  // A row with no identifier and no date is not a lead, it is a blank line
  // left at the bottom of a spreadsheet. Skip it without noise - flagging
  // trailing blanks as data quality issues trains people to ignore the list.
  if (!leadId && !rawDate && !rawStatus && rawAmount === undefined) continue;

  const recordId = leadId || ('sales-row-' + index);
  const recIssues = [];
  // Everything pushed to `issues` from here to the end of this iteration
  // belongs to this record, and gets stamped with its dates below.
  const issueStart = issues.length;

  // ---- date -------------------------------------------------
  let date = null;
  if (!rawDate) {
    recIssues.push('blank date');
    issues.push({
      source: 'sales', severity: 'warning', code: 'BLANK_DATE', record_id: recordId,
      message: 'Lead ' + recordId + ' has no date. It cannot be placed in a reporting period and is excluded from every period metric.',
    });
  } else if (!isValidISODate(rawDate)) {
    recIssues.push('invalid date "' + rawDate + '"');
    issues.push({
      source: 'sales', severity: 'warning', code: 'INVALID_DATE', record_id: recordId,
      message: 'Lead ' + recordId + ' has an invalid date "' + rawDate + '" (not a real calendar date in YYYY-MM-DD). Excluded from every period metric.',
    });
  } else {
    date = rawDate;
  }

  // ---- status -----------------------------------------------
  let status = null;
  if (!rawStatus) {
    recIssues.push('missing status');
    issues.push({
      source: 'sales', severity: 'warning', code: 'MISSING_STATUS', record_id: recordId,
      message: 'Lead ' + recordId + ' has no status. It still counts as a lead but is excluded from win rate, pipeline value and revenue.',
    });
  } else {
    const mapped = STATUS_MAP[rawStatus.toLowerCase()];
    if (mapped) {
      status = mapped;
      if (mapped !== rawStatus) {
        issues.push({
          source: 'sales', severity: 'info', code: 'STATUS_NORMALIZED', record_id: recordId,
          message: 'Lead ' + recordId + ' status "' + rawStatus + '" was read as "' + mapped + '".',
        });
      }
    } else {
      recIssues.push('unrecognised status "' + rawStatus + '"');
      issues.push({
        source: 'sales', severity: 'warning', code: 'UNKNOWN_STATUS', record_id: recordId,
        message: 'Lead ' + recordId + ' has an unrecognised status "' + rawStatus + '". Counted as a lead only.',
      });
    }
  }

  // ---- amount -----------------------------------------------
  const amount = num(rawAmount);
  const isClosedWon = status === 'Closed Won';
  const isOpen = status === 'Qualified' || status === 'Proposal Sent';

  if (amount === null && (isClosedWon || isOpen)) {
    // Only a problem where the amount is actually used. A Closed Lost deal
    // with no amount changes nothing, so it raises nothing.
    recIssues.push('missing deal amount');
    issues.push({
      source: 'sales', severity: 'warning', code: 'MISSING_AMOUNT', record_id: recordId,
      message: 'Lead ' + recordId + ' is "' + status + '" but has no deal amount. It is counted in the deal count and excluded from ' + (isClosedWon ? 'revenue won' : 'pipeline value') + '.',
    });
  }
  if (amount !== null && amount < 0) {
    recIssues.push('negative deal amount');
    issues.push({
      source: 'sales', severity: 'warning', code: 'NEGATIVE_AMOUNT', record_id: recordId,
      message: 'Lead ' + recordId + ' has a negative deal amount (' + amount + '). Kept as-is; it will pull totals down.',
    });
  }

  // ---- lead source ------------------------------------------
  let leadSource = rawSource;
  if (!leadSource) {
    leadSource = 'Unattributed';
    recIssues.push('missing lead source');
    issues.push({
      source: 'sales', severity: 'warning', code: 'MISSING_LEAD_SOURCE', record_id: recordId,
      message: 'Lead ' + recordId + ' has no lead source. Grouped under "Unattributed" so its revenue is not lost from the source breakdown.',
    });
  }

  // ---- duplicate guard --------------------------------------
  // A re-export appended to the sheet instead of replacing it is the most
  // common way this source breaks. Second copy of a lead_id is dropped from
  // the metrics and named, rather than quietly doubling revenue.
  let duplicate = false;
  if (leadId) {
    if (seenLeadIds.has(leadId)) {
      duplicate = true;
      issues.push({
        source: 'sales', severity: 'warning', code: 'DUPLICATE_RECORD', record_id: recordId,
        message: 'Lead ' + recordId + ' appears more than once in the source. Only the first copy is counted.',
      });
    }
    seenLeadIds.add(leadId);
  }

  // Stamp this record's dates onto every issue it raised. An undated lead
  // gets an empty list, which reads as "affects every period" downstream -
  // correct, because a lead with no date is excluded from all of them.
  for (let i = issueStart; i < issues.length; i++) {
    issues[i].record_dates = date ? [date] : [];
  }

  out.push({
    json: {
      _source: 'sales',
      lead_id: recordId,
      date: date,
      status: status,
      status_raw: rawStatus,
      deal_amount: amount,
      marketing_spend: num(rawSpend),
      spend_month: date ? date.slice(0, 7) : null,
      lead_source: leadSource,
      is_duplicate: duplicate,
      // usable_for_period drives every period filter downstream. No date =
      // no period = cannot be counted, however complete the rest of the row.
      usable_for_period: Boolean(date) && !duplicate,
      record_issues: recIssues,
    },
  });
}

if (out.length === 0) {
  issues.push({
    source: 'sales', severity: 'error', code: 'NO_RECORDS', record_id: null,
    message: 'The Sales source returned no usable rows. Every sales metric in this report is unavailable, not zero.',
  });
}

// Issues ride on the FIRST item so a single Code node output carries both
// the records and the diagnostics without a second branch to merge back in.
if (out.length > 0) out[0].json._source_issues = issues;
else out.push({ json: { _source: 'sales', _empty: true, _source_issues: issues } });

return out;

// n8n Code node: Normalize Project Delivery
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Normalize Project Delivery (Airtable)   (Run Once for ALL Items)
//
// Same contract as Normalize Sales: keep every record, type it, and attach
// the reasons it cannot be used rather than dropping it.
//
// ONE THING TO KNOW ABOUT THIS SOURCE
// -----------------------------------
// `status` is a SNAPSHOT of where the project stands right now. It is not
// a history. So "was this project blocked during March?" is not actually
// answerable from this data - the only honest question is "is it blocked
// now, and was it running during March?". This node computes the date span
// a project was live for; the metrics node intersects that span with the
// reporting window. The limitation is stated on the dashboard rather than
// papered over, because a leader reading "5 blocked projects" for a window
// three months ago deserves to know it means "5 blocked today, that were
// open then".
//
// The Airtable node returns fields under either `fields` or flattened onto
// the item depending on node version, so read through both.
//
// THE 100-RECORD CLIFF
// --------------------
// Airtable's REST API returns at most 100 records per response and hands
// back an `offset` cursor for the next page. The n8n node only follows that
// cursor when "Return All" is on; with it off it stops after one page and
// reports success. There is no error, no warning, and no total count in the
// response to compare against - a truncated fetch and a small table look
// EXACTLY the same from here. So the guard below is a heuristic on the one
// signal there is: a record count that lands exactly on a page boundary is
// far more likely to be a truncated fetch than a coincidence.
// ============================================================

// Airtable's page size. Not configurable, and the number the node's default
// `limit` happens to match, which is why both failure modes land here.
const AIRTABLE_PAGE_SIZE = 100;

const ISO = /^\d{4}-\d{2}-\d{2}$/;

const STATUS_MAP = {
  'completed': 'Completed', 'complete': 'Completed', 'done': 'Completed',
  'in progress': 'In Progress', 'inprogress': 'In Progress', 'active': 'In Progress', 'ongoing': 'In Progress',
  'blocked': 'Blocked', 'on hold': 'Blocked', 'onhold': 'Blocked', 'stalled': 'Blocked',
};

function isValidISODate(s) {
  if (typeof s !== 'string' || !ISO.test(s)) return false;
  const d = new Date(s + 'T00:00:00Z');
  if (Number.isNaN(d.getTime())) return false;
  return d.toISOString().slice(0, 10) === s;
}

function num(v) {
  if (v === null || v === undefined) return null;
  const raw = String(v).trim();
  if (raw === '') return null;
  const cleaned = raw.replace(/[^0-9.\-]/g, '');
  if (cleaned === '' || cleaned === '-' || cleaned === '.') return null;
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : null;
}

function str(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

// The delivery CSV ships with a UTF-8 BOM, so the first header is
// "﻿project_id" and a naive row['project_id'] is undefined. Strip it
// here rather than in a preceding node, so the fix travels with the reader.
function field(row, names) {
  const norm = {};
  for (const k of Object.keys(row)) {
    norm[k.replace(/^﻿/, '').toLowerCase().replace(/[\s_\-]/g, '')] = row[k];
  }
  for (const n of names) {
    const key = n.toLowerCase().replace(/[\s_\-]/g, '');
    if (norm[key] !== undefined) return norm[key];
  }
  return undefined;
}

function daysBetween(a, b) {
  return Math.round((new Date(b + 'T00:00:00Z').getTime() - new Date(a + 'T00:00:00Z').getTime()) / 86400000);
}

const rows = $input.all();
const out = [];
const issues = [];
const seenIds = new Set();

let index = 0;
for (const item of rows) {
  const raw = item.json || {};
  index += 1;
  // Every issue raised while reading this row is stamped with the row's own
  // dates at the end of the iteration, so Compute Metrics can tell a warning
  // about work inside the reporting window from one about work outside it.
  const issueStart = issues.length;

  if (raw.error) {
    issues.push({
      source: 'delivery', severity: 'error', code: 'SOURCE_ERROR', record_id: null,
      message: 'Airtable returned an error: ' + String(raw.error).slice(0, 200),
    });
    continue;
  }

  const row = (raw.fields && typeof raw.fields === 'object') ? Object.assign({}, raw.fields, raw) : raw;

  const projectId = str(field(row, ['project_id', 'projectid', 'id']));
  const name = str(field(row, ['project_name', 'name', 'project']));
  const team = str(field(row, ['team']));
  const owner = str(field(row, ['owner', 'assignee']));
  const rawKickoff = str(field(row, ['kickoff_date', 'kickoff', 'start_date']));
  const rawDue = str(field(row, ['due_date', 'due']));
  const rawCompleted = str(field(row, ['completed_date', 'completed']));
  const rawStatus = str(field(row, ['status']));
  const budgeted = num(field(row, ['budgeted_cost', 'budget']));
  const actual = num(field(row, ['actual_cost', 'actual']));

  if (!projectId && !name && !rawStatus && !rawKickoff) continue; // trailing blank line

  const recordId = projectId || ('delivery-row-' + index);
  const recIssues = [];

  // ---- dates ------------------------------------------------
  function readDate(value, label, severity) {
    if (!value) return null;
    if (!isValidISODate(value)) {
      recIssues.push('invalid ' + label + ' "' + value + '"');
      issues.push({
        source: 'delivery', severity: severity, code: 'INVALID_DATE', record_id: recordId,
        message: 'Project ' + recordId + ' has an invalid ' + label + ' "' + value + '". Treated as missing.',
      });
      return null;
    }
    return value;
  }

  const kickoff = readDate(rawKickoff, 'kickoff date', 'warning');
  const due = readDate(rawDue, 'due date', 'warning');
  const completed = readDate(rawCompleted, 'completed date', 'warning');

  if (!rawKickoff) {
    recIssues.push('blank kickoff date');
    issues.push({
      source: 'delivery', severity: 'warning', code: 'BLANK_DATE', record_id: recordId,
      message: 'Project ' + recordId + ' has no kickoff date, so the workflow cannot tell when it was live. Excluded from active-project and delivery-load counts.',
    });
  }

  // ---- status -----------------------------------------------
  let status = null;
  if (!rawStatus) {
    recIssues.push('missing status');
    issues.push({
      source: 'delivery', severity: 'warning', code: 'MISSING_STATUS', record_id: recordId,
      message: 'Project ' + recordId + ' has no status. Excluded from active, blocked and completed counts.',
    });
  } else {
    status = STATUS_MAP[rawStatus.toLowerCase()] || null;
    if (!status) {
      recIssues.push('unrecognised status "' + rawStatus + '"');
      issues.push({
        source: 'delivery', severity: 'warning', code: 'UNKNOWN_STATUS', record_id: recordId,
        message: 'Project ' + recordId + ' has an unrecognised status "' + rawStatus + '". Excluded from status-based counts.',
      });
    }
  }

  // ---- cross-field sanity -----------------------------------
  // These catch the errors a per-field validator cannot see. A project
  // marked Completed with no completed date will silently vanish from the
  // completed count, and without this line nobody would know why.
  if (status === 'Completed' && !completed) {
    recIssues.push('completed with no completed date');
    issues.push({
      source: 'delivery', severity: 'warning', code: 'MISSING_COMPLETED_DATE', record_id: recordId,
      message: 'Project ' + recordId + ' is marked Completed but has no completed date. It cannot be placed in a period and is excluded from completion, on-time and budget metrics.',
    });
  }
  if (status === 'Completed' && !due) {
    issues.push({
      source: 'delivery', severity: 'warning', code: 'MISSING_DUE_DATE', record_id: recordId,
      message: 'Project ' + recordId + ' completed without a due date. Counted as completed, excluded from the on-time completion rate (which has no baseline to measure against).',
    });
  }
  if (status === 'Completed' && actual === null) {
    issues.push({
      source: 'delivery', severity: 'warning', code: 'MISSING_ACTUAL_COST', record_id: recordId,
      message: 'Project ' + recordId + ' completed with no actual cost. Counted as completed, excluded from budget variance and the over-budget count.',
    });
  }
  if (status === 'Completed' && budgeted === null) {
    issues.push({
      source: 'delivery', severity: 'warning', code: 'MISSING_BUDGET', record_id: recordId,
      message: 'Project ' + recordId + ' completed with no budgeted cost. Excluded from budget variance.',
    });
  }
  if (kickoff && completed && daysBetween(kickoff, completed) < 0) {
    recIssues.push('completed before kickoff');
    issues.push({
      source: 'delivery', severity: 'warning', code: 'IMPLAUSIBLE_DATES', record_id: recordId,
      message: 'Project ' + recordId + ' has a completed date (' + completed + ') before its kickoff date (' + kickoff + '). Dates kept as given; treat its timeline metrics with caution.',
    });
  }
  if (status !== 'Completed' && completed) {
    issues.push({
      source: 'delivery', severity: 'info', code: 'STATUS_DATE_MISMATCH', record_id: recordId,
      message: 'Project ' + recordId + ' has a completed date but its status is "' + (status || rawStatus || 'blank') + '". Status is treated as the source of truth.',
    });
  }

  let duplicate = false;
  if (projectId) {
    if (seenIds.has(projectId)) {
      duplicate = true;
      issues.push({
        source: 'delivery', severity: 'warning', code: 'DUPLICATE_RECORD', record_id: recordId,
        message: 'Project ' + recordId + ' appears more than once in the source. Only the first copy is counted.',
      });
    }
    seenIds.add(projectId);
  }

  // ---- derived ----------------------------------------------
  const delayDays = (due && completed) ? daysBetween(due, completed) : null;

  out.push({
    json: {
      _source: 'delivery',
      project_id: recordId,
      project_name: name,
      team: team || 'Unassigned',
      owner: owner || 'Unassigned',
      kickoff_date: kickoff,
      due_date: due,
      completed_date: completed,
      status: status,
      status_raw: rawStatus,
      budgeted_cost: budgeted,
      actual_cost: actual,
      // Positive = late by n days, 0 = on the day, negative = early.
      delay_days: delayDays,
      // null, not 0 - "we do not know" must not read as "on budget".
      budget_variance: (budgeted !== null && actual !== null) ? (actual - budgeted) : null,
      // The window this project was live for. `null` end means still open.
      // The metrics node intersects this with the reporting period.
      live_from: kickoff,
      live_to: completed,
      is_duplicate: duplicate,
      usable_for_period: Boolean(kickoff || completed) && !duplicate,
      record_issues: recIssues,
    },
  });

  if (!team) {
    issues.push({
      source: 'delivery', severity: 'warning', code: 'MISSING_TEAM', record_id: recordId,
      message: 'Project ' + recordId + ' has no team. Grouped under "Unassigned" in delivery load.',
    });
  }

  // All three dates, not just one: a project that kicked off in April and
  // completed in June is inside both windows, and a warning about it should
  // appear in whichever one the reader has selected.
  const stamp = [kickoff, due, completed].filter(function (d) { return Boolean(d); });
  for (let i = issueStart; i < issues.length; i++) {
    issues[i].record_dates = stamp;
  }
}

if (out.length === 0) {
  issues.push({
    source: 'delivery', severity: 'error', code: 'NO_RECORDS', record_id: null,
    message: 'The Project Delivery source returned no usable rows. Every delivery metric in this report is unavailable, not zero.',
  });
}

// An exact multiple of the page size means the fetch stopped precisely where
// a page ends. That is either a genuine coincidence or a silently truncated
// read, and the difference is invisible from here - so say so rather than
// reporting a confident number built on a partial table. Every delivery
// metric is a count or an average over the set, so truncation understates
// all of them at once and nothing downstream would notice.
if (rows.length > 0 && rows.length % AIRTABLE_PAGE_SIZE === 0) {
  issues.push({
    source: 'delivery', severity: 'error', code: 'POSSIBLE_TRUNCATION', record_id: null,
    message: 'The Project Delivery source returned exactly ' + rows.length + ' records, which is a whole number of Airtable pages. Airtable pages at ' + AIRTABLE_PAGE_SIZE + ' records, so this is very likely a truncated read rather than the whole table. Check that "Return All" is enabled on the Airtable node. Every delivery metric in this report may be understated.',
  });
}

if (out.length > 0) out[0].json._source_issues = issues;
else out.push({ json: { _source: 'delivery', _empty: true, _source_issues: issues } });

return out;

// n8n Code node: Normalize People Ops
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Normalize People Ops (HTTP API)         (Run Once for ALL Items)
//
// The API answers with ONE item: { source, record_count, records: [...] }.
// This node unrolls it, types each record, and flags what is wrong.
//
// WHY THE HTTP NODE FETCHES THE WHOLE DATASET AND FILTERS HERE
// ------------------------------------------------------------
// The API accepts ?start= and ?end=. Using them looks like the efficient
// choice and it is the wrong one, because the five People Ops metrics each
// key off a DIFFERENT date:
//
//   applications   -> application_date in the window
//   offers         -> offer_accepted_date in the window
//   new hires      -> start_date in the window
//   exits          -> exit_date in the window
//   headcount      -> started on or before the window END and had not left
//                     -> needs people who started in 2025, years outside it
//
// One server-side range cannot serve all five. Ask for June only and
// headcount collapses from ~80 to a handful, and the number still looks
// perfectly plausible on a dashboard. The dataset is 92 records; pulling
// all of it costs one request. Correctness wins by a mile.
//
// STATUS IS A CROSS-CHECK, NOT THE SOURCE OF TRUTH FOR HEADCOUNT
// --------------------------------------------------------------
// Headcount is derived from DATES: started on or before period end, and no
// exit date on or before period end. A record with a blank status therefore
// still counts correctly, and a record marked Active with a start date in
// the future correctly does NOT. Both are still reported as data quality
// issues - handled is not the same as hidden.
// ============================================================

const ISO = /^\d{4}-\d{2}-\d{2}$/;
const VALID_STATUS = ['Active', 'Exited', 'Candidate'];

function isValidISODate(s) {
  if (typeof s !== 'string' || !ISO.test(s)) return false;
  const d = new Date(s + 'T00:00:00Z');
  if (Number.isNaN(d.getTime())) return false;
  return d.toISOString().slice(0, 10) === s;
}

function str(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

function daysBetween(a, b) {
  return Math.round((new Date(b + 'T00:00:00Z').getTime() - new Date(a + 'T00:00:00Z').getTime()) / 86400000);
}

const issues = [];
const out = [];
const seenIds = new Set();

// ---- unwrap the response ------------------------------------
// Tolerate: the documented envelope, a bare array, or n8n having already
// split the array into items. All three shapes have shown up in testing
// depending on how the HTTP node's response options are set.
let records = [];
let envelope = {};
const items = $input.all();

for (const item of items) {
  const j = item.json || {};

  if (j.error) {
    issues.push({
      source: 'people_ops', severity: 'error', code: 'SOURCE_ERROR', record_id: null,
      message: 'The People Ops API request failed: ' + String(j.error && (j.error.message || j.error) || j.error).slice(0, 200),
    });
    continue;
  }

  if (Array.isArray(j.records)) {
    envelope = j;
    records = records.concat(j.records);
  } else if (Array.isArray(j)) {
    records = records.concat(j);
  } else if (j.employee_id !== undefined) {
    records.push(j);
  }
}

// The API tells us how many records exist in total. If we received fewer,
// something truncated the response and every headcount number is understated.
// A silently short read is the single most dangerous failure this source has,
// because nothing about the output looks wrong.
const declared = Number(envelope.record_count);
const available = Number(envelope.total_available_records);
if (Number.isFinite(declared) && declared !== records.length) {
  issues.push({
    source: 'people_ops', severity: 'error', code: 'TRUNCATED_RESPONSE', record_id: null,
    message: 'The API declared ' + declared + ' records but ' + records.length + ' were received. People Ops metrics are incomplete.',
  });
}
if (Number.isFinite(available) && Number.isFinite(declared) && declared < available) {
  issues.push({
    source: 'people_ops', severity: 'warning', code: 'FILTERED_RESPONSE', record_id: null,
    message: 'The API returned ' + declared + ' of ' + available + ' records, so a server-side filter was applied. Headcount and attrition need the unfiltered set to be correct.',
  });
}

let index = 0;
for (const rec of records) {
  index += 1;
  const r = rec || {};
  // Issues raised for this employee are stamped with the employee's own
  // lifecycle dates below, so a warning can be matched to the reporting
  // window rather than shown under every period regardless.
  const issueStart = issues.length;

  const employeeId = str(r.employee_id) || ('people-row-' + index);
  const department = str(r.department);
  const role = str(r.role);
  const rawStatus = str(r.status);
  const recIssues = [];

  function readDate(value, label, required) {
    const v = str(value);
    if (!v) {
      if (required) {
        recIssues.push('blank ' + label);
        issues.push({
          source: 'people_ops', severity: 'warning', code: 'BLANK_DATE', record_id: employeeId,
          message: 'Employee ' + employeeId + ' has no ' + label + '. Excluded from metrics that depend on it.',
        });
      }
      return null;
    }
    if (!isValidISODate(v)) {
      recIssues.push('invalid ' + label + ' "' + v + '"');
      issues.push({
        source: 'people_ops', severity: 'warning', code: 'INVALID_DATE', record_id: employeeId,
        message: 'Employee ' + employeeId + ' has an invalid ' + label + ' "' + v + '". Treated as missing.',
      });
      return null;
    }
    return v;
  }

  const applicationDate = readDate(r.application_date, 'application date', true);
  const offerDate = readDate(r.offer_accepted_date, 'offer accepted date', false);
  const startDate = readDate(r.start_date, 'start date', false);
  const exitDate = readDate(r.exit_date, 'exit date', false);

  // ---- status -----------------------------------------------
  let status = null;
  if (!rawStatus) {
    recIssues.push('missing status');
    issues.push({
      source: 'people_ops', severity: 'warning', code: 'MISSING_STATUS', record_id: employeeId,
      message: 'Employee ' + employeeId + ' has a blank status. Headcount is derived from start and exit dates, so this record is still counted correctly, but its lifecycle stage cannot be confirmed.',
    });
  } else if (VALID_STATUS.indexOf(rawStatus) === -1) {
    const match = VALID_STATUS.filter(function (s) { return s.toLowerCase() === rawStatus.toLowerCase(); })[0];
    if (match) { status = match; }
    else {
      recIssues.push('unrecognised status "' + rawStatus + '"');
      issues.push({
        source: 'people_ops', severity: 'warning', code: 'UNKNOWN_STATUS', record_id: employeeId,
        message: 'Employee ' + employeeId + ' has an unrecognised status "' + rawStatus + '".',
      });
    }
  } else {
    status = rawStatus;
  }

  if (!department) {
    recIssues.push('missing department');
    issues.push({
      source: 'people_ops', severity: 'warning', code: 'MISSING_DEPARTMENT', record_id: employeeId,
      message: 'Employee ' + employeeId + ' has no department. Grouped under "Unassigned" in the headcount breakdown.',
    });
  }

  // ---- cross-field sanity -----------------------------------
  if (status === 'Exited' && !exitDate) {
    issues.push({
      source: 'people_ops', severity: 'warning', code: 'MISSING_EXIT_DATE', record_id: employeeId,
      message: 'Employee ' + employeeId + ' is marked Exited but has no exit date. They will still be counted in headcount, and are missing from the exit count.',
    });
  }
  if (exitDate && status !== 'Exited') {
    issues.push({
      source: 'people_ops', severity: 'info', code: 'STATUS_DATE_MISMATCH', record_id: employeeId,
      message: 'Employee ' + employeeId + ' has an exit date but a status of "' + (status || 'blank') + '". Dates drive headcount, so the exit is honoured.',
    });
  }
  if (applicationDate && startDate && daysBetween(applicationDate, startDate) < 0) {
    recIssues.push('start date before application date');
    issues.push({
      source: 'people_ops', severity: 'warning', code: 'IMPLAUSIBLE_DATES', record_id: employeeId,
      message: 'Employee ' + employeeId + ' has a start date (' + startDate + ') before their application date (' + applicationDate + '). Excluded from time to hire.',
    });
  }
  if (startDate && exitDate && daysBetween(startDate, exitDate) < 0) {
    issues.push({
      source: 'people_ops', severity: 'warning', code: 'IMPLAUSIBLE_DATES', record_id: employeeId,
      message: 'Employee ' + employeeId + ' has an exit date (' + exitDate + ') before their start date (' + startDate + ').',
    });
  }

  let duplicate = false;
  if (str(r.employee_id)) {
    if (seenIds.has(employeeId)) {
      duplicate = true;
      issues.push({
        source: 'people_ops', severity: 'warning', code: 'DUPLICATE_RECORD', record_id: employeeId,
        message: 'Employee ' + employeeId + ' appears more than once in the API response. Only the first copy is counted.',
      });
    }
    seenIds.add(employeeId);
  }

  const timeToHire = (applicationDate && startDate && daysBetween(applicationDate, startDate) >= 0)
    ? daysBetween(applicationDate, startDate) : null;
  const offerTime = (applicationDate && offerDate && daysBetween(applicationDate, offerDate) >= 0)
    ? daysBetween(applicationDate, offerDate) : null;

  // An employment record spans up to four dates and can legitimately touch
  // several reporting windows. All of them are stamped; the window test
  // downstream is "any of these dates falls inside".
  const stamp = [applicationDate, offerDate, startDate, exitDate]
    .filter(function (d) { return Boolean(d); });
  for (let i = issueStart; i < issues.length; i++) {
    issues[i].record_dates = stamp;
  }

  out.push({
    json: {
      _source: 'people_ops',
      employee_id: employeeId,
      department: department || 'Unassigned',
      role: role,
      application_date: applicationDate,
      offer_accepted_date: offerDate,
      start_date: startDate,
      exit_date: exitDate,
      status: status,
      status_raw: rawStatus,
      time_to_hire_days: timeToHire,
      offer_acceptance_days: offerTime,
      is_duplicate: duplicate,
      usable_for_period: !duplicate,
      record_issues: recIssues,
    },
  });
}

if (out.length === 0) {
  issues.push({
    source: 'people_ops', severity: 'error', code: 'NO_RECORDS', record_id: null,
    message: 'The People Ops API returned no usable records. Every People Ops metric in this report is unavailable, not zero.',
  });
}

if (out.length > 0) out[0].json._source_issues = issues;
else out.push({ json: { _source: 'people_ops', _empty: true, _source_issues: issues } });

return out;

// n8n Code node: Compute Metrics
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Compute Metrics                         (Run Once for ALL Items)
//
// The analytical core. Every number the dashboard shows and every number
// Claude is given is produced here, in one deterministic pass, with no
// model involved. Claude interprets these figures; it never produces them.
// That split is the whole reliability story: an LLM that miscounts is a
// bug you cannot see, so the LLM is not allowed to count.
//
// The same function runs TWICE - once over the selected period and once
// over the comparison window - so "win rate declined" is a measured delta
// and not a model's impression.
//
// THREE JUDGEMENT CALLS, MADE EXPLICITLY:
//
// 1. MARKETING SPEND IS NOT A COLUMN SUM. The source repeats one monthly
//    budget on every row of that month. Summing it over the full history
//    returns 291,800 against a true 33,500, and cost per lead inherits the
//    error. Spend is collapsed to one figure per calendar month and then
//    pro-rated across the window's partial months.
//
// 2. A MISSING INPUT MAKES A METRIC UNAVAILABLE, NOT ZERO. Every ratio
//    returns null when its denominator is empty, and every null carries a
//    stated reason. A dashboard showing "0%" win rate when there were no
//    closed deals is lying; "not enough data" is the truth.
//
// 3. EVERY METRIC REPORTS WHAT IT COUNTED. Each figure ships with the
//    number of records included and excluded, so any number on the
//    dashboard can be reconciled against the source without opening n8n.
//
// 4. DATA QUALITY IS SCOPED TO THE SELECTED WINDOW. A warning about a
//    lead from March is not a warning about a June report. The normalizers
//    stamp every issue with the dates of the record it came from; this node
//    keeps the ones that touch the window, and folds the rest into a single
//    counted line. See "data quality, scoped to the window" below.
//
// 5. EVERY DOMAIN ALSO REPORTS ITS SHAPE, not only its total. A window's
//    figures cannot answer "is this getting worse?" - so each domain emits
//    a bucketed series across the window (daily, weekly or monthly, chosen
//    by span) which the dashboard draws as trend charts and Claude reads
//    as movement it did not have to infer.
// ============================================================

const period = $('Resolve Reporting Period').first().json;

function pull(nodeName) {
  // A source node that failed outright leaves nothing to reference. Return
  // an empty set and let the missing-source check downstream report it,
  // rather than throwing and taking the whole report down with it.
  try { return $(nodeName).all().map(function (i) { return i.json || {}; }); }
  catch (e) { return []; }
}

const salesRaw = pull('Normalize Sales');
const deliveryRaw = pull('Normalize Delivery');
const peopleRaw = pull('Normalize People Ops');

// A DEPLOYMENT problem and a DATA problem are different things and must not
// share a channel. An unset Supabase URL will break the write, but it says
// nothing about whether the numbers are trustworthy - and letting it into
// data_quality would downgrade the report's confidence badge for a reason
// that has nothing to do with the report.
const CONFIG_CODES = ['SUPABASE_URL_NOT_SET'];
const periodWarnings = period.period_warnings || [];
const configErrors = periodWarnings.filter(function (w) { return CONFIG_CODES.indexOf(w.code) >= 0; });

// Diagnostics were attached to the first item of each source.
const dataQuality = []
  .concat((salesRaw[0] && salesRaw[0]._source_issues) || [])
  .concat((deliveryRaw[0] && deliveryRaw[0]._source_issues) || [])
  .concat((peopleRaw[0] && peopleRaw[0]._source_issues) || [])
  .concat(periodWarnings
    .filter(function (w) { return CONFIG_CODES.indexOf(w.code) === -1; })
    .map(function (w) {
      return { source: 'period', severity: w.severity, code: w.code, record_id: null, message: w.message };
    }));

const sales = salesRaw.filter(function (r) { return r._source === 'sales' && !r._empty; });
const delivery = deliveryRaw.filter(function (r) { return r._source === 'delivery' && !r._empty; });
const people = peopleRaw.filter(function (r) { return r._source === 'people_ops' && !r._empty; });

// ---- small numeric helpers ----------------------------------
function inRange(d, start, end) { return Boolean(d) && d >= start && d <= end; }
function round(n, dp) {
  if (n === null || n === undefined || !Number.isFinite(n)) return null;
  const f = Math.pow(10, dp === undefined ? 2 : dp);
  return Math.round(n * f) / f;
}
function sum(arr) { return arr.reduce(function (a, b) { return a + b; }, 0); }
function mean(arr) { return arr.length ? sum(arr) / arr.length : null; }
function addDays(s, n) {
  const d = new Date(s + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}
function daysBetween(a, b) {
  return Math.round((new Date(b + 'T00:00:00Z').getTime() - new Date(a + 'T00:00:00Z').getTime()) / 86400000);
}
function pad2(n) { return String(n).padStart(2, '0'); }
function nextMonth(ym) {
  const y = Number(ym.slice(0, 4));
  const m = Number(ym.slice(5, 7));
  return m === 12 ? (y + 1) + '-01' : y + '-' + pad2(m + 1);
}
function uniq(arr) { return Array.from(new Set(arr)); }
function daysInMonth(ym) {
  const y = Number(ym.slice(0, 4));
  const m = Number(ym.slice(5, 7));
  return new Date(Date.UTC(y, m, 0)).getUTCDate();
}
// A metric that could not be computed. The reason travels with the null so
// the dashboard and Claude both explain the gap instead of showing a dash.
function unavailable(reason) { return { value: null, unavailable_reason: reason }; }
function value(v) { return { value: v, unavailable_reason: null }; }

// ---- marketing spend ----------------------------------------
// Build the month -> budget map ONCE, from the whole dataset rather than
// the window, so a window covering half of June still knows June's budget.
const spendByMonth = {};
const spendConflicts = {};
for (const r of sales) {
  if (!r.spend_month || r.marketing_spend === null || r.marketing_spend === undefined) continue;
  if (spendByMonth[r.spend_month] === undefined) {
    spendByMonth[r.spend_month] = r.marketing_spend;
  } else if (spendByMonth[r.spend_month] !== r.marketing_spend) {
    // If the assumption ever breaks - two different budgets in one month -
    // the code must not quietly pick one. Keep the max and say so.
    spendConflicts[r.spend_month] = true;
    spendByMonth[r.spend_month] = Math.max(spendByMonth[r.spend_month], r.marketing_spend);
  }
}
for (const m of Object.keys(spendConflicts)) {
  dataQuality.push({
    source: 'sales', severity: 'warning', code: 'SPEND_CONFLICT', record_id: null,
    message: 'Month ' + m + ' carries more than one marketing spend figure. The highest was used; marketing spend for any window covering ' + m + ' is approximate.',
  });
}

// Pro-rates each month's budget by how much of it the window covers.
// "Last 30 days" = 31 May - 30 Jun takes 1/31 of May's budget and all of
// June's. Straight-summing the months touched would count a whole month of
// May spend for a single day of it.
function computeMarketingSpend(start, end, reportIssues) {
  let total = 0;
  const months = [];
  const missing = [];
  let cursor = start.slice(0, 7);
  const lastMonth = end.slice(0, 7);

  while (cursor <= lastMonth) {
    const dim = daysInMonth(cursor);
    const monthStart = cursor + '-01';
    const monthEnd = cursor + '-' + String(dim).padStart(2, '0');
    const overlapStart = monthStart > start ? monthStart : start;
    const overlapEnd = monthEnd < end ? monthEnd : end;
    const covered = Math.round((new Date(overlapEnd + 'T00:00:00Z') - new Date(overlapStart + 'T00:00:00Z')) / 86400000) + 1;

    if (spendByMonth[cursor] === undefined) {
      missing.push(cursor);
    } else {
      const share = spendByMonth[cursor] * (covered / dim);
      total += share;
      months.push({ month: cursor, monthly_spend: spendByMonth[cursor], days_covered: covered, days_in_month: dim, attributed: round(share) });
    }

    const y = Number(cursor.slice(0, 4));
    const m = Number(cursor.slice(5, 7));
    cursor = m === 12 ? (y + 1) + '-01' : y + '-' + String(m + 1).padStart(2, '0');
  }

  if (missing.length && reportIssues) {
    dataQuality.push({
      source: 'sales', severity: 'warning', code: 'MISSING_SPEND_MONTH', record_id: null,
      message: 'No marketing spend figure exists for ' + missing.join(', ') + '. Marketing spend and cost per lead for this period are understated.',
    });
  }

  return { total: round(total), months: months, missing_months: missing };
}

// ============================================================
// SALES
// ============================================================
function computeSales(start, end, reportIssues) {
  const excludedNoDate = sales.filter(function (r) { return !r.usable_for_period; }).length;
  const rows = sales.filter(function (r) { return r.usable_for_period && inRange(r.date, start, end); });

  const won = rows.filter(function (r) { return r.status === 'Closed Won'; });
  const lost = rows.filter(function (r) { return r.status === 'Closed Lost'; });
  const open = rows.filter(function (r) { return r.status === 'Qualified' || r.status === 'Proposal Sent'; });
  const noStatus = rows.filter(function (r) { return r.status === null; });

  const wonWithAmount = won.filter(function (r) { return r.deal_amount !== null; });
  const openWithAmount = open.filter(function (r) { return r.deal_amount !== null; });

  const revenueWon = sum(wonWithAmount.map(function (r) { return r.deal_amount; }));
  const pipelineValue = sum(openWithAmount.map(function (r) { return r.deal_amount; }));

  const decided = won.length + lost.length;
  const spend = computeMarketingSpend(start, end, reportIssues);

  // Revenue by lead source. Every source that appeared in the window is
  // listed even at zero revenue - a source that generated 12 leads and no
  // revenue is exactly the finding leadership needs, and dropping the empty
  // rows would hide it.
  //
  // Each source carries its OWN full picture - leads, both closed states,
  // open pipeline, its own win rate - not just a revenue total. The
  // dashboard's per-source panel and Claude's source-level commentary both
  // read this, and neither can be assembled from a single number per row.
  const bySource = {};
  for (const r of rows) {
    const k = r.lead_source || 'Unattributed';
    if (!bySource[k]) bySource[k] = {
      lead_source: k, leads: 0, closed_won: 0, closed_lost: 0, open_deals: 0,
      revenue_won: 0, pipeline_value: 0, deals_missing_amount: 0, no_status: 0,
    };
    const b = bySource[k];
    b.leads += 1;
    if (r.status === 'Closed Won') {
      b.closed_won += 1;
      if (r.deal_amount !== null) b.revenue_won += r.deal_amount;
      else b.deals_missing_amount += 1;
    } else if (r.status === 'Closed Lost') {
      b.closed_lost += 1;
    } else if (r.status === 'Qualified' || r.status === 'Proposal Sent') {
      b.open_deals += 1;
      if (r.deal_amount !== null) b.pipeline_value += r.deal_amount;
    } else if (r.status === null) {
      b.no_status += 1;
    }
  }
  const revenueByLeadSource = Object.keys(bySource)
    .map(function (k) {
      const b = bySource[k];
      const decidedHere = b.closed_won + b.closed_lost;
      const wonWithAmountHere = b.closed_won - b.deals_missing_amount;
      return {
        lead_source: b.lead_source,
        leads: b.leads,
        closed_won: b.closed_won,
        closed_lost: b.closed_lost,
        open_deals: b.open_deals,
        no_status: b.no_status,
        revenue_won: round(b.revenue_won),
        pipeline_value: round(b.pipeline_value),
        deals_missing_amount: b.deals_missing_amount,
        // null, never 0: a source with nothing decided has no win rate, and
        // painting it 0% would read as "we lose everything from Referral".
        win_rate: decidedHere > 0 ? round(b.closed_won / decidedHere, 4) : null,
        average_won_deal: wonWithAmountHere > 0 ? round(b.revenue_won / wonWithAmountHere) : null,
        share_of_revenue: revenueWon > 0 ? round(b.revenue_won / revenueWon, 4) : null,
      };
    })
    .sort(function (a, b) { return b.revenue_won - a.revenue_won; });

  if (reportIssues && rows.length === 0) {
    dataQuality.push({
      source: 'sales', severity: 'warning', code: 'EMPTY_PERIOD', record_id: null,
      message: 'No Sales records fall inside ' + start + ' to ' + end + '. Sales metrics for this period are unavailable, not zero.',
    });
  }

  return {
    total_leads: value(rows.length),
    closed_won_deals: value(won.length),
    closed_lost_deals: value(lost.length),
    pipeline_value: openWithAmount.length || open.length === 0
      ? value(round(pipelineValue))
      : unavailable('All ' + open.length + ' open deals in this period are missing a deal amount.'),
    revenue_won: wonWithAmount.length || won.length === 0
      ? value(round(revenueWon))
      : unavailable('All ' + won.length + ' closed-won deals in this period are missing a deal amount.'),
    win_rate: decided > 0
      ? value(round(won.length / decided, 4))
      : unavailable('No deals were closed won or closed lost in this period, so there is no win rate to compute.'),
    marketing_spend: spend.total !== null && spend.months.length
      ? value(spend.total)
      : unavailable('No marketing spend figure is available for any month in this period.'),
    cost_per_lead: (rows.length > 0 && spend.months.length)
      ? value(round(spend.total / rows.length))
      : unavailable(rows.length === 0 ? 'No leads in this period, so cost per lead has no denominator.' : 'No marketing spend figure is available for this period.'),
    revenue_by_lead_source: value(revenueByLeadSource),
    average_won_deal_value: wonWithAmount.length
      ? value(round(revenueWon / wonWithAmount.length))
      : unavailable('No closed-won deals with an amount in this period.'),
    _coverage: {
      records_in_period: rows.length,
      records_excluded_no_usable_date: excludedNoDate,
      deals_missing_status: noStatus.length,
      won_missing_amount: won.length - wonWithAmount.length,
      open_missing_amount: open.length - openWithAmount.length,
      marketing_spend_basis: spend.months.length
        ? 'One budget figure per calendar month, pro-rated by days covered: ' + spend.months.map(function (m) { return m.month + ' ' + m.days_covered + '/' + m.days_in_month + ' of ' + m.monthly_spend; }).join('; ')
        : 'No monthly spend figure available for this window.',
      marketing_spend_months: spend.months,
    },
  };
}

// ============================================================
// PROJECT DELIVERY
// ============================================================
function computeDelivery(start, end, reportIssues) {
  // "Active during the period" = the project's live span overlaps the
  // window AND it is open today. See the snapshot caveat in the normalizer.
  function overlaps(r) {
    if (!r.live_from) return false;
    if (r.live_from > end) return false;
    if (r.live_to && r.live_to < start) return false;
    return true;
  }

  const usable = delivery.filter(function (r) { return r.usable_for_period; });
  const openNow = usable.filter(function (r) { return r.status === 'In Progress' || r.status === 'Blocked'; });

  const active = openNow.filter(overlaps);
  const blocked = active.filter(function (r) { return r.status === 'Blocked'; });
  const completed = usable.filter(function (r) { return r.status === 'Completed' && inRange(r.completed_date, start, end); });

  const completedWithDue = completed.filter(function (r) { return r.due_date !== null; });
  const onTime = completedWithDue.filter(function (r) { return r.delay_days !== null && r.delay_days <= 0; });
  const late = completedWithDue.filter(function (r) { return r.delay_days !== null && r.delay_days > 0; });

  const costed = completed.filter(function (r) { return r.budget_variance !== null; });
  const variance = sum(costed.map(function (r) { return r.budget_variance; }));
  const overBudget = costed.filter(function (r) { return r.budget_variance > 0; });

  // Delivery load by team. Uses the union of teams seen across the whole
  // source, not just this window, so a team that shipped nothing appears
  // as a zero row instead of disappearing - silence is a finding.
  const allTeams = {};
  for (const r of usable) allTeams[r.team] = true;
  const byTeam = Object.keys(allTeams).sort().map(function (team) {
    const a = active.filter(function (r) { return r.team === team; });
    const c = completed.filter(function (r) { return r.team === team; });
    const blockedHere = a.filter(function (r) { return r.status === 'Blocked'; });
    const withDue = c.filter(function (r) { return r.due_date !== null; });
    const onTimeHere = withDue.filter(function (r) { return r.delay_days !== null && r.delay_days <= 0; });
    const lateHere = withDue.filter(function (r) { return r.delay_days !== null && r.delay_days > 0; });
    const costedHere = c.filter(function (r) { return r.budget_variance !== null; });
    return {
      team: team,
      active: a.length,
      blocked: blockedHere.length,
      completed: c.length,
      completed_on_time: onTimeHere.length,
      completed_late: lateHere.length,
      // Same rule as the headline metric: no completions with a due date
      // means there is no rate, not a rate of zero.
      on_time_rate: withDue.length > 0 ? round(onTimeHere.length / withDue.length, 4) : null,
      average_delay_days: lateHere.length ? round(mean(lateHere.map(function (r) { return r.delay_days; })), 1) : null,
      worst_delay_days: lateHere.length ? Math.max.apply(null, lateHere.map(function (r) { return r.delay_days; })) : null,
      budget_variance: costedHere.length ? round(sum(costedHere.map(function (r) { return r.budget_variance; }))) : null,
      // null, not 0, when nothing this team completed carries both costs -
      // "0 over budget" and "we cannot tell" are different claims, and the
      // team panel showed them as the same one.
      over_budget: costedHere.length ? costedHere.filter(function (r) { return r.budget_variance > 0; }).length : null,
      missing_due_date: c.length - withDue.length,
      missing_cost: c.length - costedHere.length,
      owners: uniq(a.concat(c).map(function (r) { return r.owner; })).sort(),
      // The named work behind the counts, so the team panel on the dashboard
      // can say WHICH project is blocked instead of only how many are.
      blocked_items: blockedHere.map(function (r) {
        return { project_id: r.project_id, project_name: r.project_name, owner: r.owner, due_date: r.due_date };
      }),
      late_items: lateHere
        .slice()
        .sort(function (x, y) { return y.delay_days - x.delay_days; })
        .slice(0, 5)
        .map(function (r) {
          return { project_id: r.project_id, project_name: r.project_name, owner: r.owner, delay_days: r.delay_days };
        }),
      total_load: a.length + c.length,
    };
  }).sort(function (x, y) { return y.total_load - x.total_load; });

  const byOwner = {};
  for (const r of active.concat(completed)) {
    if (!byOwner[r.owner]) byOwner[r.owner] = { owner: r.owner, team: r.team, active: 0, blocked: 0, completed: 0, completed_late: 0 };
  }
  for (const r of active) {
    byOwner[r.owner].active += 1;
    if (r.status === 'Blocked') byOwner[r.owner].blocked += 1;
  }
  for (const r of completed) {
    byOwner[r.owner].completed += 1;
    if (r.delay_days !== null && r.delay_days > 0) byOwner[r.owner].completed_late += 1;
  }

  if (reportIssues && active.length === 0 && completed.length === 0) {
    dataQuality.push({
      source: 'delivery', severity: 'warning', code: 'EMPTY_PERIOD', record_id: null,
      message: 'No projects were active or completed between ' + start + ' and ' + end + '. Delivery metrics for this period are unavailable, not zero.',
    });
  }

  return {
    active_projects: value(active.length),
    completed_projects: value(completed.length),
    blocked_projects: value(blocked.length),
    on_time_completion_rate: completedWithDue.length > 0
      ? value(round(onTime.length / completedWithDue.length, 4))
      : unavailable(completed.length === 0
        ? 'No projects completed in this period.'
        : 'None of the ' + completed.length + ' projects completed in this period has a due date to measure against.'),
    average_delay_days: late.length > 0
      ? value(round(mean(late.map(function (r) { return r.delay_days; })), 1))
      : unavailable(completedWithDue.length === 0
        ? 'No completed projects with a due date in this period.'
        : 'No project completed late in this period.'),
    budget_variance: costed.length > 0
      ? value(round(variance))
      : unavailable('No project completed in this period has both a budgeted and an actual cost.'),
    over_budget_projects: costed.length > 0
      ? value(overBudget.length)
      : unavailable('No project completed in this period has both a budgeted and an actual cost.'),
    delivery_load_by_team: value(byTeam),
    delivery_load_by_owner: value(Object.keys(byOwner).map(function (k) { return byOwner[k]; })
      .sort(function (a, b) { return (b.active + b.completed) - (a.active + a.completed); })),
    budgeted_cost_total: costed.length ? value(round(sum(costed.map(function (r) { return r.budgeted_cost; })))) : unavailable('No costed completions in this period.'),
    actual_cost_total: costed.length ? value(round(sum(costed.map(function (r) { return r.actual_cost; })))) : unavailable('No costed completions in this period.'),
    _coverage: {
      projects_completed_in_period: completed.length,
      completed_missing_due_date: completed.length - completedWithDue.length,
      completed_missing_cost: completed.length - costed.length,
      late_completions: late.length,
      worst_delay_days: late.length ? Math.max.apply(null, late.map(function (r) { return r.delay_days; })) : null,
      blocked_project_ids: blocked.map(function (r) { return r.project_id; }),
      status_is_point_in_time_snapshot: true,
    },
  };
}

// ============================================================
// PEOPLE OPS
// ============================================================
function computePeople(start, end, reportIssues) {
  const usable = people.filter(function (r) { return r.usable_for_period; });

  // Headcount is derived from dates, never from the status string, so a
  // record with a blank status is still counted correctly.
  function headcountAsOf(asOf) {
    return usable.filter(function (r) {
      if (!r.start_date || r.start_date > asOf) return false;
      if (r.exit_date && r.exit_date <= asOf) return false;
      return true;
    });
  }

  const applications = usable.filter(function (r) { return inRange(r.application_date, start, end); });
  const offers = usable.filter(function (r) { return inRange(r.offer_accepted_date, start, end); });
  const newHires = usable.filter(function (r) { return inRange(r.start_date, start, end); });
  const exits = usable.filter(function (r) { return inRange(r.exit_date, start, end); });

  const headcountEnd = headcountAsOf(end);
  const headcountOpen = headcountAsOf(addDays(start, -1)); // the day before the window opens

  // People marked Active whose start date is after the window closes have
  // accepted an offer but are not yet staff. Counting them as headcount
  // overstates capacity; ignoring them entirely hides a real pipeline.
  const notYetStarted = usable.filter(function (r) { return r.start_date && r.start_date > end; });
  if (reportIssues && notYetStarted.length) {
    dataQuality.push({
      source: 'people_ops', severity: 'info', code: 'FUTURE_START_DATE', record_id: null,
      message: notYetStarted.length + ' record(s) have a start date after ' + end + '. They are accepted offers, not headcount, and are excluded from active headcount for this period.',
    });
  }

  const tth = newHires.map(function (r) { return r.time_to_hire_days; }).filter(function (v) { return v !== null; });
  const oat = offers.map(function (r) { return r.offer_acceptance_days; }).filter(function (v) { return v !== null; });

  const allDepts = {};
  for (const r of usable) allDepts[r.department] = true;
  const inDept = function (list, dept) {
    return list.filter(function (r) { return r.department === dept; });
  };
  const byDept = Object.keys(allDepts).sort().map(function (dept) {
    const endHere = inDept(headcountEnd, dept);
    const openHere = inDept(headcountOpen, dept);
    const hiresHere = inDept(newHires, dept);
    const exitsHere = inDept(exits, dept);
    const offersHere = inDept(offers, dept);
    const tthHere = hiresHere.map(function (r) { return r.time_to_hire_days; }).filter(function (x) { return x !== null; });
    const oatHere = offersHere.map(function (r) { return r.offer_acceptance_days; }).filter(function (x) { return x !== null; });
    return {
      department: dept,
      active_headcount: endHere.length,
      opening_headcount: openHere.length,
      headcount_change: endHere.length - openHere.length,
      new_hires: hiresHere.length,
      exits: exitsHere.length,
      applications: inDept(applications, dept).length,
      offers_accepted: offersHere.length,
      accepted_not_started: inDept(notYetStarted, dept).length,
      // Department attrition on the same basis as the headline figure:
      // exits over the headcount this department opened the window with.
      attrition_rate: openHere.length > 0 ? round(exitsHere.length / openHere.length, 4) : null,
      time_to_hire_days: tthHere.length ? round(mean(tthHere), 1) : null,
      offer_acceptance_days: oatHere.length ? round(mean(oatHere), 1) : null,
      roles: uniq(endHere.map(function (r) { return r.role; }).filter(Boolean)).sort().slice(0, 8),
    };
  }).sort(function (a, b) { return b.active_headcount - a.active_headcount; });

  // A department with nothing at all in the window is a reportable gap -
  // it is usually a broken feed, not a quiet quarter.
  if (reportIssues) {
    const silent = byDept.filter(function (d) { return d.applications === 0 && d.new_hires === 0 && d.exits === 0; });
    if (silent.length) {
      dataQuality.push({
        source: 'people_ops', severity: 'info', code: 'DEPARTMENT_NO_ACTIVITY', record_id: null,
        message: 'No applications, hires or exits recorded between ' + start + ' and ' + end + ' for: ' + silent.map(function (d) { return d.department; }).join(', ') + '.',
      });
    }
  }

  return {
    applications: value(applications.length),
    offers_accepted: value(offers.length),
    new_hires: value(newHires.length),
    exits: value(exits.length),
    active_headcount: value(headcountEnd.length),
    opening_headcount: value(headcountOpen.length),
    time_to_hire_days: tth.length
      ? value(round(mean(tth), 1))
      : unavailable(newHires.length === 0
        ? 'Nobody started in this period, so there is no time to hire to average.'
        : 'None of the ' + newHires.length + ' new hires has both an application and a start date.'),
    offer_acceptance_days: oat.length
      ? value(round(mean(oat), 1))
      : unavailable(offers.length === 0
        ? 'No offers were accepted in this period.'
        : 'None of the offers accepted in this period has an application date to measure from.'),
    attrition_rate: headcountOpen.length > 0
      ? value(round(exits.length / headcountOpen.length, 4))
      : unavailable('Opening headcount was zero on ' + addDays(start, -1) + ', so attrition has no denominator.'),
    headcount_by_department: value(byDept),
    accepted_offers_not_yet_started: value(notYetStarted.length),
    _coverage: {
      total_records_considered: usable.length,
      records_missing_application_date: usable.filter(function (r) { return !r.application_date; }).length,
      records_missing_status: usable.filter(function (r) { return r.status === null; }).length,
      candidates_without_offer: usable.filter(function (r) { return !r.offer_accepted_date && !r.start_date; }).length,
      headcount_basis: 'Derived from start and exit dates as at ' + end + ', not from the status field.',
      exits_by_department: exits.reduce(function (acc, r) { acc[r.department] = (acc[r.department] || 0) + 1; return acc; }, {}),
    },
  };
}

// ============================================================
// TREND SERIES — the shape of the window
//
// The tiles answer "how much"; they cannot answer "is this getting worse".
// So each domain also emits a bucketed series across the SELECTED window,
// which the dashboard draws as trend charts and which Claude is given as
// measured movement rather than something it has to infer from two totals.
//
// TWO DECISIONS WORTH KNOWING ABOUT:
//
// 1. THE GRAIN FOLLOWS THE SPAN. A 7-day window bucketed monthly is one
//    bar; a year bucketed daily is 180 points of noise. Days up to three
//    weeks, weeks up to four months, calendar months beyond that.
//
// 2. BUCKETS ARE CUT BACKWARDS FROM THE PERIOD END, so the most recent
//    bucket is always whole. Cutting forwards from the start leaves the
//    LAST bucket short, and a short final bucket draws as a cliff — the
//    classic "our revenue collapsed" chart that is really "the week is
//    only half over". The short bucket ends up first, where it is
//    obviously the edge of the window, and it is flagged `partial` so the
//    chart can mark it.
// ============================================================
function buildBuckets(start, end) {
  const spanDays = daysBetween(start, end) + 1;
  const grain = spanDays <= 21 ? 'day' : (spanDays <= 120 ? 'week' : 'month');
  const buckets = [];

  if (grain === 'month') {
    let cursor = start.slice(0, 7);
    const lastMonth = end.slice(0, 7);
    while (cursor <= lastMonth) {
      const dim = daysInMonth(cursor);
      const monthStart = cursor + '-01';
      const monthEnd = cursor + '-' + pad2(dim);
      const bStart = monthStart > start ? monthStart : start;
      const bEnd = monthEnd < end ? monthEnd : end;
      buckets.push({
        bucket_start: bStart,
        bucket_end: bEnd,
        label: cursor,
        partial: bStart !== monthStart || bEnd !== monthEnd,
      });
      cursor = nextMonth(cursor);
    }
  } else {
    const size = grain === 'day' ? 1 : 7;
    let bEnd = end;
    while (bEnd >= start) {
      let bStart = addDays(bEnd, -(size - 1));
      const partial = bStart < start;
      if (partial) bStart = start;
      buckets.unshift({
        bucket_start: bStart,
        bucket_end: bEnd,
        label: size === 1 ? bStart : (bStart + ' to ' + bEnd),
        partial: partial,
      });
      bEnd = addDays(bStart, -1);
    }
  }

  return { grain: grain, buckets: buckets };
}

function buildTrendSeries(start, end) {
  const plan = buildBuckets(start, end);
  const usableSales = sales.filter(function (r) { return r.usable_for_period; });
  const usableDelivery = delivery.filter(function (r) { return r.usable_for_period; });
  const usablePeople = people.filter(function (r) { return r.usable_for_period; });

  const out = { sales: [], delivery: [], people_ops: [] };

  for (const b of plan.buckets) {
    const bs = b.bucket_start;
    const be = b.bucket_end;
    const days = daysBetween(bs, be) + 1;
    const meta = { bucket_start: bs, bucket_end: be, label: b.label, grain: plan.grain, partial: b.partial, days: days };

    // --- sales
    const leads = usableSales.filter(function (r) { return inRange(r.date, bs, be); });
    const wonHere = leads.filter(function (r) { return r.status === 'Closed Won'; });
    const lostHere = leads.filter(function (r) { return r.status === 'Closed Lost'; });
    const wonAmounts = wonHere.filter(function (r) { return r.deal_amount !== null; });
    const decidedHere = wonHere.length + lostHere.length;
    out.sales.push(Object.assign({}, meta, {
      leads: leads.length,
      closed_won: wonHere.length,
      closed_lost: lostHere.length,
      revenue_won: round(sum(wonAmounts.map(function (r) { return r.deal_amount; }))),
      win_rate: decidedHere > 0 ? round(wonHere.length / decidedHere, 4) : null,
    }));

    // --- delivery
    const completedHere = usableDelivery.filter(function (r) {
      return r.status === 'Completed' && inRange(r.completed_date, bs, be);
    });
    const lateHere = completedHere.filter(function (r) { return r.delay_days !== null && r.delay_days > 0; });
    out.delivery.push(Object.assign({}, meta, {
      kickoffs: usableDelivery.filter(function (r) { return inRange(r.kickoff_date, bs, be); }).length,
      completed: completedHere.length,
      completed_late: lateHere.length,
      completed_on_time: completedHere.filter(function (r) { return r.delay_days !== null && r.delay_days <= 0; }).length,
      average_delay_days: lateHere.length ? round(mean(lateHere.map(function (r) { return r.delay_days; })), 1) : null,
    }));

    // --- people ops
    // Headcount is a stock, not a flow: it is measured AT the bucket end
    // from start and exit dates, the same way the headline figure is.
    out.people_ops.push(Object.assign({}, meta, {
      applications: usablePeople.filter(function (r) { return inRange(r.application_date, bs, be); }).length,
      offers_accepted: usablePeople.filter(function (r) { return inRange(r.offer_accepted_date, bs, be); }).length,
      new_hires: usablePeople.filter(function (r) { return inRange(r.start_date, bs, be); }).length,
      exits: usablePeople.filter(function (r) { return inRange(r.exit_date, bs, be); }).length,
      active_headcount: usablePeople.filter(function (r) {
        if (!r.start_date || r.start_date > be) return false;
        if (r.exit_date && r.exit_date <= be) return false;
        return true;
      }).length,
    }));
  }

  return { grain: plan.grain, series: out };
}

// ---- run both windows ---------------------------------------
const current = {
  sales: computeSales(period.period_start, period.period_end, true),
  delivery: computeDelivery(period.period_start, period.period_end, true),
  people_ops: computePeople(period.period_start, period.period_end, true),
};
// The comparison window must not add data quality noise: an issue in a
// window nobody is looking at would clutter the report for the one they are.
const previous = {
  sales: computeSales(period.compare_start, period.compare_end, false),
  delivery: computeDelivery(period.compare_start, period.compare_end, false),
  people_ops: computePeople(period.compare_start, period.compare_end, false),
};

// The series is attached to the domain blocks as an array-valued metric, so
// it travels to Supabase through the same breakdown path as the other
// grouped figures - no new table, no new write node, one shape to render.
const trendSeries = buildTrendSeries(period.period_start, period.period_end);
current.sales.trend_series = value(trendSeries.series.sales);
current.delivery.trend_series = value(trendSeries.series.delivery);
current.people_ops.trend_series = value(trendSeries.series.people_ops);

// ---- a dead source is UNKNOWN, not zero ---------------------
// Every count above is a count of the rows that arrived. When a source
// arrived with nothing at all - a 401 from Airtable, a Sheets outage - that
// arithmetic is still correct and completely misleading: "0 active projects"
// is a measurement, and what actually happened is that nobody measured.
// A dashboard cannot tell the two apart from the number, and neither can a
// reader, so the figures for a source that did not answer are replaced with
// nulls that carry the reason.
//
// This is NOT the same as a source that answered and had nothing in the
// window. That is a real zero, it is reported as one, and EMPTY_PERIOD says
// so - which is why the test is on the SOURCE returning no rows at all,
// not on the window being empty.
const SOURCE_SYSTEMS = {
  sales: 'Sales (Google Sheets)',
  delivery: 'Project Delivery (Airtable)',
  people_ops: 'People Ops (API)',
};

function markSourceUnavailable(block, domainKey) {
  const reason = 'The ' + SOURCE_SYSTEMS[domainKey] + ' source returned no records for this run, ' +
    'so this figure is unknown rather than zero.';
  for (const k of Object.keys(block)) {
    if (k === '_coverage') continue;
    const node = block[k];
    if (!node || typeof node !== 'object' || !('value' in node)) continue;
    // A grouped figure becomes an empty list with the same reason attached,
    // so a breakdown chart renders "unavailable" instead of a set of zero bars.
    block[k] = Array.isArray(node.value)
      ? { value: [], unavailable_reason: reason }
      : unavailable(reason);
  }
}

const sourceRowsReceived = { sales: sales.length, delivery: delivery.length, people_ops: people.length };
for (const domainKey of ['sales', 'delivery', 'people_ops']) {
  if (sourceRowsReceived[domainKey] > 0) continue;
  markSourceUnavailable(current[domainKey], domainKey);
  markSourceUnavailable(previous[domainKey], domainKey);
}

// ---- deltas -------------------------------------------------
// Only across scalars, and only where BOTH windows produced a number.
// Comparing against a null would manufacture a trend out of missing data.
const TRENDED = {
  sales: ['total_leads', 'closed_won_deals', 'closed_lost_deals', 'pipeline_value', 'revenue_won', 'win_rate', 'marketing_spend', 'cost_per_lead', 'average_won_deal_value'],
  delivery: ['active_projects', 'completed_projects', 'blocked_projects', 'on_time_completion_rate', 'average_delay_days', 'budget_variance', 'over_budget_projects'],
  people_ops: ['applications', 'offers_accepted', 'new_hires', 'exits', 'active_headcount', 'time_to_hire_days', 'offer_acceptance_days', 'attrition_rate'],
};

const trends = {};
for (const domain of Object.keys(TRENDED)) {
  trends[domain] = {};
  for (const key of TRENDED[domain]) {
    const now = current[domain][key];
    const then = previous[domain][key];
    if (!now || !then || now.value === null || then.value === null) {
      trends[domain][key] = { current: now ? now.value : null, previous: then ? then.value : null, change: null, percent_change: null, direction: 'not_comparable' };
      continue;
    }
    const change = round(now.value - then.value, 4);

    // A percent change is only meaningful when the baseline is non-zero AND
    // the sign did not flip. Budget variance moving from -100 (under budget)
    // to +1050 (over budget) is a real and important change, but rendering
    // it as "+1150%" is noise dressed as precision. Suppress the percentage
    // and let the dashboard fall back to the absolute figures, which say the
    // useful thing: it went from 100 under to 1,050 over.
    const signFlipped = (then.value < 0) !== (now.value < 0);
    const pct = (then.value !== 0 && !signFlipped)
      ? round((now.value - then.value) / Math.abs(then.value), 4)
      : null;
    trends[domain][key] = {
      current: now.value,
      previous: then.value,
      change: change,
      percent_change: pct,
      // 2% is the noise floor. Below it, "stable" is the honest word, and
      // it stops Claude narrating a trend out of a rounding difference.
      direction: change === 0 ? 'flat' : (pct !== null && Math.abs(pct) < 0.02 ? 'stable' : (change > 0 ? 'up' : 'down')),
    };
  }
}

// ---- data quality, scoped to the window ---------------------
// The normalizers read the WHOLE source, so they see every issue in it -
// including issues in records the selected window never touches. Showing
// those under a heading that says "Last 30 days" is wrong twice over: the
// warning count contradicts the numbers above it, and a genuine in-window
// problem is buried among a hundred historical ones.
//
// So each issue is placed against the window using the record dates the
// normalizers stamped on it:
//
//   in_period       the record touches the window - shown, and counted
//   run             no record behind it (a source outage, an empty period,
//                   a missing spend month) - shown; it describes THIS run
//   undated_record  a record with no usable date at all - shown, because it
//                   is excluded from every window including this one
//   out_of_period   a dated record outside the window - NOT shown as its own
//                   row; folded into one counted line so the issue is still
//                   discoverable without drowning the panel
function scopeOf(w) {
  const dates = Array.isArray(w.record_dates) ? w.record_dates.filter(Boolean) : [];
  if (!dates.length) return w.record_id ? 'undated_record' : 'run';
  for (const d of dates) {
    if (inRange(d, period.period_start, period.period_end)) return 'in_period';
  }
  return 'out_of_period';
}

const scopedDataQuality = [];
const outOfPeriodIssues = [];

for (const w of dataQuality) {
  const dates = (Array.isArray(w.record_dates) ? w.record_dates.filter(Boolean) : []).slice().sort();
  const scope = scopeOf(w);
  const row = {
    source: w.source,
    severity: w.severity,
    code: w.code,
    record_id: w.record_id || null,
    message: w.message,
    record_date: dates.length ? dates[0] : null,
    scope: scope,
    in_period: scope !== 'out_of_period',
  };
  if (scope === 'out_of_period') outOfPeriodIssues.push(row);
  else scopedDataQuality.push(row);
}

if (outOfPeriodIssues.length) {
  const counts = {};
  for (const w of outOfPeriodIssues) counts[w.code] = (counts[w.code] || 0) + 1;
  const summary = Object.keys(counts).sort()
    .map(function (c) { return c + ' x' + counts[c]; })
    .join(', ');
  scopedDataQuality.push({
    source: 'period',
    severity: 'info',
    code: 'OUTSIDE_SELECTED_PERIOD',
    record_id: null,
    // Deliberately info, and deliberately last: it must not colour the
    // report's confidence badge, because it says nothing about the numbers
    // on screen. It exists so nobody concludes the sources are clean.
    message: outOfPeriodIssues.length + ' further source issue(s) affect records dated outside ' +
      period.period_start + ' to ' + period.period_end + ', so they are not counted against this report: ' +
      summary + '. Widen the period to see them individually.',
    record_date: null,
    scope: 'run',
    in_period: true,
  });
}

// ---- source health ------------------------------------------
const sourceHealth = {
  sales: { records_received: sourceRowsReceived.sales, healthy: sourceRowsReceived.sales > 0 },
  delivery: { records_received: sourceRowsReceived.delivery, healthy: sourceRowsReceived.delivery > 0 },
  people_ops: { records_received: sourceRowsReceived.people_ops, healthy: sourceRowsReceived.people_ops > 0 },
};
const failedSources = Object.keys(sourceHealth).filter(function (k) { return !sourceHealth[k].healthy; });

// A run missing a whole source is still published - a partial report beats
// no report - but it is labelled `partial` so nobody reads it as complete.
const runStatus = failedSources.length === 0
  ? 'succeeded'
  : (failedSources.length === 3 ? 'failed' : 'partial');

const errorCount = scopedDataQuality.filter(function (d) { return d.severity === 'error'; }).length;
const warningCount = scopedDataQuality.filter(function (d) { return d.severity === 'warning'; }).length;

// ---- content fingerprint ------------------------------------
// A cheap, stable hash of the numbers only. If nothing moved since the last
// run of this period, the Claude call is skipped and the stored insight is
// reused. Re-running the same report at 6am and 6:05am should not cost twice.
function fingerprint(obj) {
  const s = JSON.stringify(obj);
  let h1 = 0x811c9dc5;
  let h2 = 0x01000193;
  for (let i = 0; i < s.length; i++) {
    h1 = (h1 ^ s.charCodeAt(i)) >>> 0;
    h1 = (h1 * 0x01000193) >>> 0;
    h2 = (h2 + s.charCodeAt(i) * (i + 1)) >>> 0;
  }
  return (h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0'));
}

const metricsHash = fingerprint({ c: current, p: previous, w: period.period_start + period.period_end });

return [{
  json: {
    run_id: period.run_id,
    period: {
      key: period.period_key,
      label: period.period_label,
      start: period.period_start,
      end: period.period_end,
      days: period.period_days,
      reference_date: period.reference_date,
      compare_label: period.compare_label,
      compare_start: period.compare_start,
      compare_end: period.compare_end,
    },
    metrics: current,
    previous_period_metrics: previous,
    trends: trends,
    data_quality: scopedDataQuality,
    data_quality_summary: {
      errors: errorCount,
      warnings: warningCount,
      info: scopedDataQuality.length - errorCount - warningCount,
      total: scopedDataQuality.length,
      // Kept visible rather than dropped: "12 issues, none of them in this
      // window" is a different statement from "no issues".
      outside_period: outOfPeriodIssues.length,
      affected_sources: uniq(scopedDataQuality.map(function (d) { return d.source; })),
    },
    trend_grain: trendSeries.grain,
    source_health: sourceHealth,
    config_errors: configErrors,
    run_status: runStatus,
    failed_sources: failedSources,
    metrics_hash: metricsHash,
    force_refresh: period.force_refresh === true,
    requested_by: period.requested_by,
    computed_at: new Date().toISOString(),
  },
}];

// n8n Code node: Build Claude Brief
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Build Claude Brief                      (Run Once for ALL Items)
//
// Turns the metrics payload into the exact request body sent to the
// Messages API. The prompt lives HERE, in a versioned Code node, rather
// than in an HTTP node's parameter box - a prompt is the most-edited and
// least-reviewed part of an AI workflow, and it deserves to sit somewhere
// a diff can be read.
//
// WHAT CLAUDE IS AND IS NOT ASKED TO DO
// --------------------------------------
// It receives ~40 finished numbers, their comparison values, and a data
// quality digest. It never sees a raw row and is never asked to count
// anything. Sending 313 rows would cost roughly 20x the tokens and invite
// arithmetic the workflow has already done correctly and deterministically.
// The division is the point: n8n owns the arithmetic, Claude owns the
// judgement, and a wrong number can only ever come from code you can test.
//
// THE ALLOWED-FIGURES LIST
// ------------------------
// Every number in the brief is also collected into `allowed_figures`. The
// parse node checks the model's prose against it and flags any figure that
// did not come from the data. That is how "grounded in the calculated
// metrics, not unsupported assumptions" gets enforced rather than merely
// requested in a prompt.
// ============================================================

const m = $input.first().json;

const MODEL = 'claude-sonnet-5';

// max_tokens is the ceiling on EVERYTHING the model emits, and on Sonnet 5
// that includes its thinking. Thinking is adaptive and ON BY DEFAULT here --
// omitting the parameter does not turn it off -- so a tight ceiling is spent
// reasoning before a single character of the answer is written. At 2000 this
// node failed exactly that way: usage came back thinking_tokens 2000 /
// output_tokens 2000, stop_reason max_tokens, and content held one thinking
// block and no text block. The run looked like "Claude returned an empty
// response" when the model had simply been cut off mid-thought.
//
// 16000 is the documented default for a non-streaming request: enough room
// that thinking plus a ~600-token JSON object never collides with the cap,
// and still well under the SDK's HTTP timeout. It is a CEILING, not a
// reservation -- a typical run finishes far below it and is billed on what
// it actually emits, so raising it costs nothing when it is not needed.
// Depth of reasoning is controlled by output_config.effort below, which is
// the knob to turn for cost; max_tokens is the safety net, not the budget.
const MAX_TOKENS = 16000;

function flat(node) {
  // {value, unavailable_reason} -> either the value, or a phrase that says
  // WHY it is missing. Claude must never see a bare null, because a bare
  // null is indistinguishable from zero once it is inside a sentence.
  if (node && typeof node === 'object' && 'value' in node) {
    return node.value === null ? { unavailable: node.unavailable_reason } : node.value;
  }
  return node;
}

function flatten(domain) {
  const out = {};
  for (const k of Object.keys(domain)) {
    if (k === '_coverage') continue;
    // The bucketed series is sent separately, under a key that says what it
    // is. Left inline it reads as just another metric and the model quotes a
    // single bucket as if it were the period total.
    if (k === 'trend_series') continue;
    out[k] = flat(domain[k]);
  }
  return out;
}

// The series, trimmed to what a sentence can use: the bucket, the flows, and
// nothing else. `partial` is kept because the first bucket of a window is
// usually short, and a model told only the number will read the dip as a fall.
function trimSeries(rows, keys) {
  return (rows || []).map(function (b) {
    const out = { bucket: b.label, days: b.days };
    if (b.partial) out.partial_bucket = true;
    for (const k of keys) out[k] = b[k];
    return out;
  });
}

function trimTrends(t) {
  // Only movements worth a sentence. Sending 24 rows of "flat" invites the
  // model to write about the ones that did not move.
  const out = {};
  for (const k of Object.keys(t)) {
    const x = t[k];
    if (x.direction === 'not_comparable' || x.direction === 'flat' || x.direction === 'stable') continue;
    out[k] = {
      now: x.current,
      was: x.previous,
      change: x.change,
      percent_change: x.percent_change,
      direction: x.direction,
    };
  }
  return out;
}

// Group the data quality list by code so 40 identical warnings arrive as
// one line with a count, not 40 lines that crowd out the numbers.
const dqByCode = {};
for (const d of m.data_quality) {
  const key = d.source + '/' + d.code;
  if (!dqByCode[key]) dqByCode[key] = { source: d.source, code: d.code, severity: d.severity, count: 0, examples: [], message: d.message };
  dqByCode[key].count += 1;
  if (d.record_id && dqByCode[key].examples.length < 3) dqByCode[key].examples.push(d.record_id);
}
const dataQualityDigest = Object.keys(dqByCode).map(function (k) { return dqByCode[k]; })
  .sort(function (a, b) {
    const rank = { error: 0, warning: 1, info: 2 };
    return (rank[a.severity] - rank[b.severity]) || (b.count - a.count);
  });

const brief = {
  reporting_period: {
    label: m.period.label,
    start: m.period.start,
    end: m.period.end,
    days: m.period.days,
    compared_against: m.period.compare_label + ' (' + m.period.compare_start + ' to ' + m.period.compare_end + ')',
  },
  sales: flatten(m.metrics.sales),
  project_delivery: flatten(m.metrics.delivery),
  people_ops: flatten(m.metrics.people_ops),
  movements_vs_comparison_period: {
    sales: trimTrends(m.trends.sales),
    project_delivery: trimTrends(m.trends.delivery),
    people_ops: trimTrends(m.trends.people_ops),
  },
  // The shape of the window, not just its total. Two totals can only say
  // "up" or "down"; this is what lets the commentary say whether something
  // is building, easing, or was one bad week.
  shape_of_the_period: {
    grain: m.trend_grain,
    note: 'Each row is one ' + m.trend_grain + ' inside the selected period. A row marked partial_bucket covers fewer days than the others and its totals are not comparable with theirs.',
    sales: trimSeries(m.metrics.sales.trend_series && m.metrics.sales.trend_series.value,
      ['leads', 'closed_won', 'closed_lost', 'revenue_won']),
    project_delivery: trimSeries(m.metrics.delivery.trend_series && m.metrics.delivery.trend_series.value,
      ['kickoffs', 'completed', 'completed_late']),
    people_ops: trimSeries(m.metrics.people_ops.trend_series && m.metrics.people_ops.trend_series.value,
      ['applications', 'new_hires', 'exits', 'active_headcount']),
  },
  calculation_notes: {
    marketing_spend: m.metrics.sales._coverage.marketing_spend_basis,
    headcount: m.metrics.people_ops._coverage.headcount_basis,
    delivery_status: 'Project status is a point-in-time snapshot, so "active" means open today and running at some point during the window.',
    win_rate: 'Closed won divided by closed won plus closed lost. Open deals are excluded from the denominator.',
    attrition: 'Exits in the window divided by headcount on the day before the window opened.',
  },
  records_behind_the_numbers: {
    sales: m.metrics.sales._coverage,
    project_delivery: m.metrics.delivery._coverage,
    people_ops: m.metrics.people_ops._coverage,
  },
  data_quality: dataQualityDigest,
  source_health: m.source_health,
  run_status: m.run_status,
};

// ---- the names the model is allowed to use -------------------
// Teams, departments and lead sources, exactly as they appear in the data.
// The parse node checks any `entity` the model returns against this list, so
// a finding can be filed under a real team rather than an invented one - the
// same treatment the figures get, applied to the names.
const namedEntities = []
  .concat(((m.metrics.sales.revenue_by_lead_source || {}).value || []).map(function (x) { return x.lead_source; }))
  .concat(((m.metrics.delivery.delivery_load_by_team || {}).value || []).map(function (x) { return x.team; }))
  .concat(((m.metrics.people_ops.headcount_by_department || {}).value || []).map(function (x) { return x.department; }))
  .filter(Boolean);

// ---- allowed figures ----------------------------------------
// Every number that appears anywhere in the brief, so the parse node can
// check the model's prose against the data it was given.
const allowedFigures = [];
(function walk(node) {
  if (node === null || node === undefined) return;
  if (typeof node === 'number' && Number.isFinite(node)) { allowedFigures.push(node); return; }
  if (Array.isArray(node)) { node.forEach(walk); return; }
  if (typeof node === 'object') { Object.keys(node).forEach(function (k) { walk(node[k]); }); }
})(brief);
const uniqueFigures = Array.from(new Set(allowedFigures));

// ---- prompt -------------------------------------------------
const system = [
  'You brief the commercial team at Koya Talent - sales, marketing and the people who own the revenue number. You write the commentary that sits under the numbers on their dashboard.',
  '',
  'They are smart and busy, and they are not analysts. They care about pipeline, deals won and lost, what marketing spend bought, whether delivery is protecting the client relationship, and whether hiring can keep up with demand. Write to that.',
  '',
