        additionalProperties: false,
        required: ['source', 'issue', 'impact'],
        properties: {
          source: { type: 'string', enum: ['sales', 'project_delivery', 'people_ops', 'period'] },
          issue: { type: 'string' },
          impact: { type: 'string', description: 'Which metric this makes less reliable, and how.' },
        },
      },
