// NOTE ON PARAMETERS: temperature, top_p and top_k are REMOVED on Claude
// Sonnet 5 and return a 400 if sent. Determinism is bought here with a
// structured output schema and a tightly scoped prompt instead. Sending
// `temperature: 0` out of habit is the fastest way to break this node.
// `budget_tokens` is gone the same way -- adaptive thinking replaced the
// fixed-budget form, and sending it is also a 400.
const requestBody = {
  model: MODEL,
  max_tokens: MAX_TOKENS,
  // Stated rather than omitted. Omitting it on Sonnet 5 does NOT mean "no
  // thinking" -- the model runs adaptive either way -- and a reader who
  // assumes otherwise will size max_tokens for the answer alone and
  // reintroduce the truncation above. Writing it down makes the thinking
  // budget a visible part of the request instead of an invisible default.
  // display stays at its default ('omitted'): nothing downstream reads the
  // reasoning, and it is billed identically whether or not it is returned.
  thinking: { type: 'adaptive' },
  system: system,
  messages: [{ role: 'user', content: user }],
  output_config: {
    format: { type: 'json_schema', schema: schema },
    effort: 'medium',
  },
};

// Rough token estimate at ~3.6 chars/token, used only for the cost note on
// the run record. It is an estimate and is labelled as one.
const promptChars = system.length + user.length;
const estimatedInputTokens = Math.round(promptChars / 3.6);

return [{
  json: {
    run_id: m.run_id,
    metrics_hash: m.metrics_hash,
    model: MODEL,
    request_body: requestBody,
    brief: brief,
    allowed_figures: uniqueFigures,
    allowed_entities: Array.from(new Set(namedEntities)),
    estimated_input_tokens: estimatedInputTokens,
    prompt_chars: promptChars,
  },
}];

// n8n Code node: Parse & Validate Insights
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Parse & Validate Insights               (Run Once for ALL Items)
//
// The gate between the model and the dashboard. Nothing Claude says
// reaches a stakeholder without passing through here.
//
// It does four jobs:
//
//   1. SURVIVES ANY RESPONSE. Anthropic error body, n8n error item after
//      the retries are spent, empty content, truncated JSON, a stray
//      sentence wrapped around the object - each becomes a handled outcome
//      with a reason, never a thrown exception that kills the run.
//
//   2. VALIDATES THE SHAPE. Structured outputs make a schema violation
//      unlikely, not impossible. Missing arrays are coerced to empty ones
//      and enum fields are checked, so the dashboard's rendering code can
//      trust what it is given.
//
//   3. CHECKS THE FIGURES. Every number in the model's prose is matched
//      against `allowed_figures` - the set of numbers actually present in
//      the brief. Anything unmatched is flagged as an unverified figure and
//      shown as such on the dashboard. This is the difference between
//      ASKING for grounded output and CHECKING that it is grounded.
//
//   4. FALLS BACK RATHER THAN FAILING. If the call failed or the output
//      cannot be trusted, a deterministic summary is generated from the
//      metrics themselves. The dashboard is never blank, and it always says
//      which of the two it is showing. A silent blank panel reads as "the
//      business is quiet"; an honest "AI commentary unavailable, here are
//      the numbers" does not.
// ============================================================

// Two paths reach this node: the Claude call, and the short-circuit taken
// when every source was unreachable and calling a model would be paying to
// analyse nothing. On the short-circuit, Build Claude Brief never ran - so
// its absence is an expected state, not an error.
let briefItem = { allowed_figures: [], allowed_entities: [], model: null, estimated_input_tokens: null };
try { briefItem = $('Build Claude Brief').first().json; } catch (e) { /* no-data path */ }

const metrics = $('Compute Metrics').first().json;
const response = $input.first().json || {};

const AREAS = ['sales', 'project_delivery', 'people_ops', 'cross_functional'];
const DEPARTMENTS = ['sales', 'project_delivery', 'people_ops'];
const SEVERITIES = ['high', 'medium', 'low'];
const SOURCES = ['sales', 'project_delivery', 'people_ops', 'period'];
const DEPARTMENT_LABELS = { sales: 'Sales', project_delivery: 'Project Delivery', people_ops: 'People Ops' };

// The teams, departments and lead sources that actually exist in this run's
// data. A name outside this set is treated exactly like a figure outside the
// brief: dropped, and noted. Otherwise the dashboard would file a finding
// under a team that does not exist, and the per-team panel would show it to
// whoever opened the nearest matching name.
const allowedEntities = Array.isArray(briefItem.allowed_entities) ? briefItem.allowed_entities : [];
const entityLookup = {};
for (const e of allowedEntities) entityLookup[String(e).toLowerCase()] = e;

const droppedEntities = [];
function entityOrEmpty(v) {
  const raw = str(v, 120);
  if (!raw) return '';
  const match = entityLookup[raw.toLowerCase()];
  if (match) return match;
  droppedEntities.push(raw);
  return '';
}

const validationNotes = [];

function str(v, max) {
  if (v === null || v === undefined) return '';
  return String(v).trim().slice(0, max || 2000);
}
function oneOf(v, allowed, fallback) {
  const s = str(v).toLowerCase();
  return allowed.indexOf(s) >= 0 ? s : fallback;
}

// ---- 1. did the call succeed at all? ------------------------
function readFailure() {
  // n8n's own error item, after retries are exhausted.
  if (response.error && !response.content) {
    const e = response.error;
    const detail = typeof e === 'string' ? e : str(e.message || e.description || JSON.stringify(e));
    return 'The Claude request failed: ' + detail.slice(0, 250);
  }
  // The Anthropic error body shape.
  if (response.type === 'error' && response.error) {
    return 'Claude returned an error: ' + str(response.error.type) + ' - ' + str(response.error.message).slice(0, 250);
  }
  if (!Array.isArray(response.content)) {
    return 'Claude returned no content block. Received keys: ' + Object.keys(response).join(', ').slice(0, 150);
  }
  // A refusal is a 200 with stop_reason "refusal" - it must not be read as
  // a successful empty answer.
  if (response.stop_reason === 'refusal') {
    return 'Claude declined to answer this request' + (response.stop_details && response.stop_details.category ? ' (' + response.stop_details.category + ')' : '') + '.';
  }
  return null;
}

let failure = readFailure();
let parsed = null;

if (!failure) {
  const text = response.content
    .filter(function (b) { return b && b.type === 'text'; })
    .map(function (b) { return b.text; })
    .join('\n')
    .trim();

  if (!text) {
    // An empty response has two very different causes and they need very
    // different fixes, so do not report them with one message. The common
    // one is a max_tokens cut-off: thinking is adaptive and on by default,
    // so a ceiling sized for the answer alone gets spent reasoning and the
    // turn ends with a thinking block and no text block. Saying "empty
    // response" there sends the reader looking at the prompt, which is the
    // one place the problem is not.
    if (response.stop_reason === 'max_tokens') {
      var thought = (response.usage
        && response.usage.output_tokens_details
        && response.usage.output_tokens_details.thinking_tokens) || 0;
      failure = 'Claude hit the max_tokens ceiling before writing an answer'
        + (thought ? ' (' + thought + ' of '
            + ((response.usage && response.usage.output_tokens) || thought)
            + ' output tokens went to thinking)' : '')
        + '. Raise MAX_TOKENS in Build Claude Brief, or lower output_config.effort.';
    } else {
      failure = 'Claude returned an empty response'
        + (response.stop_reason ? ' (stop_reason: ' + response.stop_reason + ')' : '') + '.';
    }
  } else {
    try {
      parsed = JSON.parse(text);
    } catch (e) {
      // Structured outputs should make this unreachable. It is kept because
      // "should be unreachable" is not a runtime guarantee, and a fenced or
      // prefaced object is trivially recoverable.
      const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
      const candidate = fenced ? fenced[1] : text;
      const a = candidate.indexOf('{');
      const b = candidate.lastIndexOf('}');
      if (a >= 0 && b > a) {
        try {
          parsed = JSON.parse(candidate.slice(a, b + 1));
          validationNotes.push('Response was not clean JSON; the object was recovered from surrounding text.');
        } catch (e2) {
          failure = 'Claude returned unparseable output: ' + str(e2.message).slice(0, 150);
        }
      } else {
        failure = 'Claude returned text with no JSON object in it.';
      }
    }
  }

  if (response.stop_reason === 'max_tokens') {
    validationNotes.push('The response hit the max_tokens ceiling and may be truncated. Raise max_tokens in Build Claude Brief if this recurs.');
  }
}

// ---- 2. deterministic fallback ------------------------------
// Built only from figures already computed. It is deliberately plain: it
// must never be mistaken for the model's analysis.
function buildFallback(reason) {
  const s = metrics.metrics.sales;
  const d = metrics.metrics.delivery;
  const h = metrics.metrics.people_ops;
  const val = function (x) { return x && x.value !== null ? x.value : null; };
  const money = function (n) { return n === null ? 'not available' : n.toLocaleString('en-GB'); };
  const rate = function (n) { return n === null ? 'not available' : (n * 100).toFixed(1) + '%'; };

  const summary = [
    'AI commentary is unavailable for this run (' + reason + '). The figures below were calculated by the workflow and are unaffected.',
    'Sales: ' + val(s.total_leads) + ' leads, ' + val(s.closed_won_deals) + ' closed won, revenue ' + money(val(s.revenue_won)) + ', win rate ' + rate(val(s.win_rate)) + '.',
    'Delivery: ' + val(d.active_projects) + ' active, ' + val(d.completed_projects) + ' completed, ' + val(d.blocked_projects) + ' blocked, on-time rate ' + rate(val(d.on_time_completion_rate)) + '.',
    'People Ops: headcount ' + val(h.active_headcount) + ', ' + val(h.new_hires) + ' new hires, ' + val(h.exits) + ' exits, attrition ' + rate(val(h.attrition_rate)) + '.',
  ].join(' ');

  // A few rules-based risks, so the fallback is still useful rather than
  // merely present.
  const risks = [];
  if (val(d.blocked_projects) > 0) {
    risks.push({
      area: 'project_delivery', entity: '', severity: val(d.blocked_projects) >= 4 ? 'high' : 'medium',
      finding: val(d.blocked_projects) + ' project(s) are currently blocked.',
      evidence: 'blocked_projects = ' + val(d.blocked_projects) + (d._coverage.blocked_project_ids.length ? ' (' + d._coverage.blocked_project_ids.join(', ') + ')' : ''),
    });
  }
  if (val(d.on_time_completion_rate) !== null && val(d.on_time_completion_rate) < 0.7) {
    risks.push({
      area: 'project_delivery', entity: '', severity: 'high',
      finding: 'On-time completion is below 70%.',
      evidence: 'on_time_completion_rate = ' + rate(val(d.on_time_completion_rate)) + ' across ' + d._coverage.projects_completed_in_period + ' completions.',
    });
  }
  if (val(d.budget_variance) !== null && val(d.budget_variance) > 0) {
    risks.push({
      area: 'project_delivery', entity: '', severity: 'medium',
      finding: 'Completed projects came in over budget in aggregate.',
      evidence: 'budget_variance = ' + money(val(d.budget_variance)) + ' across ' + val(d.over_budget_projects) + ' over-budget project(s).',
    });
  }
  if (metrics.data_quality_summary.errors > 0) {
    risks.push({
      area: 'cross_functional', entity: '', severity: 'high',
      finding: 'One or more sources reported an error during this run.',
      evidence: metrics.data_quality_summary.errors + ' error-level data quality issue(s) recorded.',
    });
  }

  // The department sections exist in the fallback too. A dashboard that
  // shows three empty department panels whenever the model call fails reads
  // as a broken dashboard; these are plain, clearly rules-based, and made
  // only of figures the workflow already computed.
  const count = function (x) { return val(x) === null ? 'not available' : String(val(x)); };
  const departments = [
    {
      area: 'sales',
      headline: count(s.total_leads) + ' leads, ' + count(s.closed_won_deals) + ' won, ' + money(val(s.revenue_won)) + ' revenue',
      assessment: 'Written without AI commentary. ' + count(s.total_leads) + ' leads were recorded, ' + count(s.closed_won_deals)
        + ' closed won and ' + count(s.closed_lost_deals) + ' closed lost, giving a win rate of ' + rate(val(s.win_rate))
        + '. Revenue won was ' + money(val(s.revenue_won)) + ' against open pipeline of ' + money(val(s.pipeline_value))
        + ', at a cost per lead of ' + money(val(s.cost_per_lead)) + '.',
      what_is_working: 'Not assessed — this run has no AI commentary.',
      what_needs_attention: 'Not assessed — this run has no AI commentary.',
      priority_action: 'Re-run the report to restore the written analysis for Sales.',
      focus_entities: [],
    },
    {
      area: 'project_delivery',
      headline: count(d.active_projects) + ' active, ' + count(d.blocked_projects) + ' blocked, ' + count(d.completed_projects) + ' completed',
      assessment: 'Written without AI commentary. ' + count(d.active_projects) + ' projects were active and '
        + count(d.completed_projects) + ' completed, of which the on-time rate was ' + rate(val(d.on_time_completion_rate))
        + '. ' + count(d.blocked_projects) + ' are blocked. Budget variance across costed completions was ' + money(val(d.budget_variance)) + '.',
      what_is_working: 'Not assessed — this run has no AI commentary.',
      what_needs_attention: 'Not assessed — this run has no AI commentary.',
      priority_action: 'Re-run the report to restore the written analysis for Project Delivery.',
      focus_entities: [],
    },
    {
      area: 'people_ops',
      headline: count(h.active_headcount) + ' active, ' + count(h.new_hires) + ' hires, ' + count(h.exits) + ' exits',
      assessment: 'Written without AI commentary. Headcount ended the period at ' + count(h.active_headcount)
        + ' after ' + count(h.new_hires) + ' new hires and ' + count(h.exits) + ' exits, an attrition rate of '
        + rate(val(h.attrition_rate)) + '. Time to hire averaged ' + (val(h.time_to_hire_days) === null ? 'not available' : val(h.time_to_hire_days) + ' days') + '.',
      what_is_working: 'Not assessed — this run has no AI commentary.',
      what_needs_attention: 'Not assessed — this run has no AI commentary.',
      priority_action: 'Re-run the report to restore the written analysis for People Ops.',
      focus_entities: [],
    },
  ];

  return {
    executive_summary: summary,
    department_insights: departments,
    risks_and_anomalies: risks,
    recommended_actions: [{
      area: 'cross_functional', entity: '', priority: 'high',
      action: 'Re-run the report to restore AI commentary, and check the n8n execution log for the failed Claude call.',
      rationale: reason,
    }],
    data_quality_warnings: metrics.data_quality
      .filter(function (w) { return w.severity === 'error' || w.severity === 'warning'; })
      .slice(0, 10)
      .map(function (w) {
        return { source: w.source === 'delivery' ? 'project_delivery' : w.source, issue: w.code + (w.record_id ? ' (' + w.record_id + ')' : ''), impact: w.message };
      }),
    confidence: 'low',
  };
}

let insights;
let insightSource;
let failureReason = null;

if (failure) {
  insights = buildFallback(failure);
  insightSource = 'deterministic_fallback';
  failureReason = failure;
} else {
  // ---- 3. normalise & validate the shape --------------------
  const p = parsed || {};

  if (typeof p.executive_summary !== 'string' || !p.executive_summary.trim()) {
    validationNotes.push('executive_summary was missing or empty.');
  }

  function normaliseList(list, name, mapper) {
    if (list === undefined || list === null) {
      validationNotes.push(name + ' was missing; treated as empty.');
      return [];
    }
    if (!Array.isArray(list)) {
      validationNotes.push(name + ' was not an array; treated as empty.');
      return [];
    }
    return list.filter(function (x) { return x && typeof x === 'object'; }).map(mapper).slice(0, 20);
  }

  // Each department gets a section or an explicit blank one. A missing
  // section must not become an absent panel: the manager who opens People
  // Ops and finds nothing cannot tell "nothing to report" from "the model
  // skipped it", and those need different reactions.
  const returnedDepartments = normaliseList(p.department_insights, 'department_insights', function (x) {
    return {
      area: oneOf(x.area, DEPARTMENTS, ''),
      headline: str(x.headline, 200),
      assessment: str(x.assessment, 2000),
      what_is_working: str(x.what_is_working, 600),
      what_needs_attention: str(x.what_needs_attention, 600),
      priority_action: str(x.priority_action, 600),
      focus_entities: (Array.isArray(x.focus_entities) ? x.focus_entities : [])
        .map(entityOrEmpty).filter(Boolean).slice(0, 6),
    };
  }).filter(function (x) { return x.area && x.assessment; });

  const departmentInsights = DEPARTMENTS.map(function (area) {
    const found = returnedDepartments.filter(function (x) { return x.area === area; })[0];
    if (found) return found;
    validationNotes.push('No department section was returned for ' + DEPARTMENT_LABELS[area] + '.');
    return {
      area: area,
      headline: 'No section returned for ' + DEPARTMENT_LABELS[area],
      assessment: 'The analysis did not include a section for ' + DEPARTMENT_LABELS[area] +
        '. The figures for it above are unaffected — they are calculated by the workflow, not written by the model.',
      what_is_working: '',
      what_needs_attention: '',
      priority_action: '',
      focus_entities: [],
      missing: true,
    };
  });

  insights = {
    executive_summary: str(p.executive_summary, 3000) || 'No executive summary was returned.',
    department_insights: departmentInsights,
    risks_and_anomalies: normaliseList(p.risks_and_anomalies, 'risks_and_anomalies', function (r) {
      return {
        area: oneOf(r.area, AREAS, 'cross_functional'),
        entity: entityOrEmpty(r.entity),
        severity: oneOf(r.severity, SEVERITIES, 'medium'),
        finding: str(r.finding, 600),
        evidence: str(r.evidence, 600),
      };
    }).filter(function (r) { return r.finding; }),
    recommended_actions: normaliseList(p.recommended_actions, 'recommended_actions', function (a) {
      return {
        area: oneOf(a.area, AREAS, 'cross_functional'),
        entity: entityOrEmpty(a.entity),
        priority: oneOf(a.priority, SEVERITIES, 'medium'),
        action: str(a.action, 600),
        rationale: str(a.rationale, 600),
      };
    }).filter(function (a) { return a.action; }),
    data_quality_warnings: normaliseList(p.data_quality_warnings, 'data_quality_warnings', function (w) {
      return {
        source: oneOf(w.source, SOURCES, 'period'),
        issue: str(w.issue, 600),
        impact: str(w.impact, 600),
      };
    }).filter(function (w) { return w.issue; }),
    confidence: oneOf(p.confidence, ['high', 'medium', 'low'], 'medium'),
  };
  insightSource = 'claude';
}

// ---- 4. groundedness check ----------------------------------
// Pull every number out of the model's prose and match it against the
// figures it was actually given. Tolerances handle honest presentation:
// a rate of 0.6 written as "60%", a rounded 2867.74 written as "2,868",
// and counts restated as words are all legitimate.
const allowed = new Set();
for (const f of (briefItem.allowed_figures || [])) {
  allowed.add(f);
  allowed.add(Math.round(f));
  allowed.add(Math.round(f * 100) / 100);
  allowed.add(Math.round(f * 100));   // 0.6 -> 60, for percentages
  allowed.add(Math.round(f * 1000) / 10);
}
// Ordinals, small counts and years are not claims about the data.
const IGNORE = new Set([0, 1, 2, 3, 4, 5, 10, 20, 25, 30, 50, 75, 90, 100, 2024, 2025, 2026, 2027]);

const prose = [
  insights.executive_summary,
  // The department sections carry more figures than anything else the model
  // writes, so leaving them out of the check would have exempted most of the
  // commentary from the one guarantee this node exists to make.
  (insights.department_insights || []).map(function (x) {
    return [x.headline, x.assessment, x.what_is_working, x.what_needs_attention, x.priority_action].join(' ');
  }).join(' '),
  insights.risks_and_anomalies.map(function (r) { return r.finding + ' ' + r.evidence; }).join(' '),
  insights.recommended_actions.map(function (a) { return a.action + ' ' + a.rationale; }).join(' '),
  insights.data_quality_warnings.map(function (w) { return w.issue + ' ' + w.impact; }).join(' '),
].join(' ');

const unverifiedFigures = [];
if (insightSource === 'claude') {
  // The lookbehind is load-bearing. A bare /-?\d.../ reads the hyphen in an
  // IDENTIFIER as a minus sign, so "PROJ-2001 and PROJ-2002 completed without
  // a due date" yields the figures -2001 and -2002, and "starts 2026-07-07"
  // yields -07 and -07. -- none of which are in allowed_figures, because none
  // of them are numbers anyone claimed. That sentence alone produces enough
  // unverified figures to trip the >2 rule and pin the report at LOW
  // confidence forever.
  //
  // Which makes it worse than a false positive: the prompt asks Claude to
  // name the offending records in data_quality_warnings, and this check then
  // punished it for complying. Doing the right thing was what capped the
  // score, so the badge moved with how many ids the commentary happened to
  // mention rather than with whether the numbers were real.
  //
  // Requiring that a digit or a leading minus not be preceded by a letter,
  // digit, underscore or hyphen keeps genuine negatives ("slipped by -12
  // days") and drops identifier and date fragments.
  const tokens = prose.match(/(?<![A-Za-z0-9_-])-?\d[\d,]*\.?\d*/g) || [];
  const checked = new Set();
  for (const t of tokens) {
    const n = Number(t.replace(/,/g, ''));
    if (!Number.isFinite(n) || IGNORE.has(n) || checked.has(n)) continue;
    checked.add(n);
    // Accept an exact match, or a match within 1% - the tolerance that
    // covers a figure quoted to fewer decimal places than it was given.
    let ok = allowed.has(n);
    if (!ok) {
      for (const f of allowed) {
        if (f !== 0 && Math.abs((n - f) / f) < 0.01) { ok = true; break; }
        if (f === 0 && n === 0) { ok = true; break; }
      }
    }
    if (!ok) unverifiedFigures.push(n);
  }
}

if (droppedEntities.length) {
  validationNotes.push('Names used in the commentary that do not exist in this run\'s data, and were dropped: ' +
    Array.from(new Set(droppedEntities)).slice(0, 8).join(', ') + '.');
}

if (unverifiedFigures.length) {
  validationNotes.push('Figures in the commentary that do not appear in the brief: ' + unverifiedFigures.slice(0, 12).join(', ') + '. Treat those statements with caution.');
}

// Confidence is capped by what the CHECK found, not by what the model
// claimed about itself. A model asserting "high" while citing figures it
// was never given must not be able to badge its own output as reliable.
let finalConfidence = insights.confidence;
if (insightSource !== 'claude') {
  finalConfidence = 'low';
} else if (unverifiedFigures.length > 2 || metrics.data_quality_summary.errors > 0) {
  finalConfidence = 'low';
} else if (unverifiedFigures.length > 0 && finalConfidence === 'high') {
  finalConfidence = 'medium';
}

const usage = response.usage || {};

return [{
  json: {
    run_id: metrics.run_id,
    metrics_hash: metrics.metrics_hash,
    insight_source: insightSource,
    model: insightSource === 'claude' ? (response.model || briefItem.model) : null,
    insights: Object.assign({}, insights, { confidence: finalConfidence }),
    model_confidence_claimed: insights.confidence,
    validation_notes: validationNotes,
    unverified_figures: unverifiedFigures,
    grounded: insightSource === 'claude' && unverifiedFigures.length === 0,
    failure_reason: failureReason,
    stop_reason: response.stop_reason || null,
    usage: {
      input_tokens: usage.input_tokens || null,
      output_tokens: usage.output_tokens || null,
      cache_read_input_tokens: usage.cache_read_input_tokens || null,
    },
    generated_at: new Date().toISOString(),
  },
}];

// n8n Code node: Build Supabase Payloads
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Build Supabase Payloads                 (Run Once for ALL Items)
//
// Assembles every row this run will write, as arrays ready for PostgREST
// bulk upsert. One item out, seven arrays on it, one HTTP node per array.
//
// WHY UPSERT AND NOT INSERT
// -------------------------
// Every row carries a deterministic natural key:
//
//   report_runs            run_id      = period + window + anchor
//   report_metrics         run_id + domain + metric_key
//   report_insights        run_id
//   report_breakdowns      run_id + domain + breakdown_key + item_key
//   data_quality_warnings  run_id + ordinal
//   sales_records          lead_id
//   delivery_projects      project_id
//   people_records         employee_id
//
// Nothing is derived from a clock or an execution id. Running the same
// period twice rewrites the same rows in place; the dashboard shows one
// report, not two, and a half-finished run that is retried lands exactly
// where the first attempt would have. That is what makes this workflow
// safe to run repeatedly, and it is a property of the KEYS, not of any
// guard node upstream.
//
// The clean records are dimension tables keyed on the business id, so
// re-running a narrow period does not delete or duplicate history - it
// refreshes the rows it touched and leaves the rest alone.
// ============================================================

const metrics = $('Compute Metrics').first().json;

// Read the insight item from THIS node's input rather than by node name, so
// both upstream paths - the Claude branch and the no-data short-circuit -
// converge here without this node needing to know which one ran.
const insightItem = $input.first().json;

let brief = { estimated_input_tokens: null };
try { brief = $('Build Claude Brief').first().json; } catch (e) { /* no-data path */ }

const runId = metrics.run_id;
const now = new Date().toISOString();

// ---- report_runs --------------------------------------------
const reportRun = {
  run_id: runId,
  period_key: metrics.period.key,
  period_label: metrics.period.label,
  period_start: metrics.period.start,
  period_end: metrics.period.end,
  period_days: metrics.period.days,
  reference_date: metrics.period.reference_date,
  compare_label: metrics.period.compare_label,
  compare_start: metrics.period.compare_start,
  compare_end: metrics.period.compare_end,
  run_status: metrics.run_status,
  // Written as 'writing'. The final node in the chain flips it to
  // 'published' once every child table has landed; the dashboard view only
  // shows published runs. A half-finished run is therefore invisible rather
  // than visible-and-empty.
  publish_state: 'writing',
  metrics_hash: metrics.metrics_hash,
  insight_source: insightItem.insight_source,
  model: insightItem.model,
  confidence: insightItem.insights.confidence,
  grounded: insightItem.grounded,
  failure_reason: insightItem.failure_reason,
  source_health: metrics.source_health,
  failed_sources: metrics.failed_sources,
  dq_errors: metrics.data_quality_summary.errors,
  dq_warnings: metrics.data_quality_summary.warnings,
  dq_info: metrics.data_quality_summary.info,
  input_tokens: insightItem.usage.input_tokens,
  output_tokens: insightItem.usage.output_tokens,
  requested_by: metrics.requested_by,
  computed_at: metrics.computed_at,
  updated_at: now,
};

// ---- report_metrics -----------------------------------------
// Long and narrow rather than one wide row per run. A new metric becomes a
// new ROW, not a schema migration and a redeploy of the dashboard - and
// every value arrives with its comparison and its unavailable_reason
// attached, so the dashboard never has to guess why a tile is blank.
const DOMAIN_MAP = { sales: 'sales', delivery: 'project_delivery', people_ops: 'people_ops' };
const reportMetrics = [];
const reportBreakdowns = [];

for (const domainKey of Object.keys(DOMAIN_MAP)) {
  const domain = DOMAIN_MAP[domainKey];
  const block = metrics.metrics[domainKey];
  const trendBlock = metrics.trends[domainKey] || {};

  for (const key of Object.keys(block)) {
    if (key.startsWith('_')) continue;
    const node = block[key];
    if (!node || typeof node !== 'object' || !('value' in node)) continue;

    // Grouped results become breakdown rows, not metric rows - a metric
    // value column holding an array would be unqueryable.
    if (Array.isArray(node.value)) {
      node.value.forEach(function (entry, i) {
        // The item key is the natural key of the row inside its breakdown, so
        // a re-run replaces "Inbound" with "Inbound" and the 24 June bucket
        // with the 24 June bucket. Falling through to the array index would
        // key a bucket on its position, and a window that gains a bucket
        // would silently rewrite every row after it.
        const itemKey = entry.lead_source || entry.team || entry.department ||
          entry.owner || entry.bucket_start || String(i);
        reportBreakdowns.push({
          run_id: runId,
          domain: domain,
          breakdown_key: key,
          item_key: String(itemKey),
          rank: i,
          values: entry,
          updated_at: now,
        });
      });
      continue;
    }

    const trend = trendBlock[key] || {};
    reportMetrics.push({
      run_id: runId,
      domain: domain,
      metric_key: key,
      metric_value: typeof node.value === 'number' ? node.value : null,
      metric_text: typeof node.value === 'number' || node.value === null ? null : String(node.value),
      is_available: node.value !== null,
      unavailable_reason: node.unavailable_reason,
      previous_value: trend.previous === undefined ? null : trend.previous,
      change: trend.change === undefined ? null : trend.change,
      percent_change: trend.percent_change === undefined ? null : trend.percent_change,
      direction: trend.direction || null,
      updated_at: now,
    });
  }
}

// ---- report_insights ----------------------------------------
const reportInsights = {
  run_id: runId,
  insight_source: insightItem.insight_source,
  model: insightItem.model,
  executive_summary: insightItem.insights.executive_summary,
  department_insights: insightItem.insights.department_insights || [],
  risks_and_anomalies: insightItem.insights.risks_and_anomalies,
  recommended_actions: insightItem.insights.recommended_actions,
  ai_data_quality_warnings: insightItem.insights.data_quality_warnings,
  confidence: insightItem.insights.confidence,
  model_confidence_claimed: insightItem.model_confidence_claimed,
  grounded: insightItem.grounded,
  unverified_figures: insightItem.unverified_figures,
  validation_notes: insightItem.validation_notes,
  failure_reason: insightItem.failure_reason,
  stop_reason: insightItem.stop_reason,
  input_tokens: insightItem.usage.input_tokens,
  output_tokens: insightItem.usage.output_tokens,
  estimated_input_tokens: brief.estimated_input_tokens,
  generated_at: insightItem.generated_at,
  updated_at: now,
};

// ---- data_quality_warnings ----------------------------------
// The ordinal makes the key deterministic without a hash. Order is stable
// because the upstream nodes walk the sources in a fixed order, so re-running
// overwrites row 7 with row 7 rather than appending a second copy.
const dqRows = metrics.data_quality.map(function (w, i) {
  return {
    run_id: runId,
    ordinal: i,
    source: w.source === 'delivery' ? 'project_delivery' : w.source,
    severity: w.severity,
    code: w.code,
    record_id: w.record_id,
    message: w.message,
    // Where the issue sits relative to the reporting window. Compute Metrics
    // has already dropped the issues that belong to other windows; these
    // columns are what let the dashboard say WHY a warning is on screen -
    // a record inside the window, a record with no date at all, or the run.
    record_date: w.record_date === undefined ? null : w.record_date,
    scope: w.scope || 'run',
    in_period: w.in_period === undefined ? true : w.in_period,
    updated_at: now,
  };
});

// ---- cleaned records ----------------------------------------
// Stored so a number on the dashboard can be traced to the rows behind it
// WITHOUT opening the source systems - which is what makes the report
// auditable by someone who has no Airtable login.
function clean(nodeName, mapper) {
  try {
    return $(nodeName).all()
      .map(function (i) { return i.json || {}; })
      .filter(function (r) { return !r._empty; })
      .map(mapper);
  } catch (e) { return []; }
}

const salesRecords = clean('Normalize Sales', function (r) {
  return {
    lead_id: r.lead_id,
    lead_date: r.date,
    status: r.status,
    status_raw: r.status_raw,
    deal_amount: r.deal_amount,
    lead_source: r.lead_source,
    spend_month: r.spend_month,
    is_usable: r.usable_for_period,
    record_issues: r.record_issues,
    last_seen_run_id: runId,
    updated_at: now,
  };
});

const deliveryProjects = clean('Normalize Delivery', function (r) {
  return {
    project_id: r.project_id,
    project_name: r.project_name,
    team: r.team,
    owner: r.owner,
    kickoff_date: r.kickoff_date,
    due_date: r.due_date,
    completed_date: r.completed_date,
    status: r.status,
    status_raw: r.status_raw,
    budgeted_cost: r.budgeted_cost,
    actual_cost: r.actual_cost,
    budget_variance: r.budget_variance,
    delay_days: r.delay_days,
    is_usable: r.usable_for_period,
    record_issues: r.record_issues,
    last_seen_run_id: runId,
    updated_at: now,
  };
});

const peopleRecords = clean('Normalize People Ops', function (r) {
  return {
    employee_id: r.employee_id,
    department: r.department,
    role: r.role,
    application_date: r.application_date,
    offer_accepted_date: r.offer_accepted_date,
    start_date: r.start_date,
    exit_date: r.exit_date,
    status: r.status,
    status_raw: r.status_raw,
    time_to_hire_days: r.time_to_hire_days,
    offer_acceptance_days: r.offer_acceptance_days,
    is_usable: r.usable_for_period,
    record_issues: r.record_issues,
    last_seen_run_id: runId,
    updated_at: now,
  };
});

return [{
  json: {
    run_id: runId,
    report_runs: [reportRun],
    report_metrics: reportMetrics,
    report_breakdowns: reportBreakdowns,
    report_insights: [reportInsights],
    data_quality_warnings: dqRows,
    sales_records: salesRecords,
    delivery_projects: deliveryProjects,
    people_records: peopleRecords,
    row_counts: {
      report_metrics: reportMetrics.length,
      report_breakdowns: reportBreakdowns.length,
      data_quality_warnings: dqRows.length,
      sales_records: salesRecords.length,
      delivery_projects: deliveryProjects.length,
      people_records: peopleRecords.length,
    },
  },
}];

// n8n Code node: Verify Publish
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Verify Publish                          (Run Once for ALL Items)
//
// The write is now a single transaction, which removes the partial-write
// problem but introduces a quieter one: with nine HTTP calls, nine things
// could visibly fail. With one, a 2xx is the only signal — and a 2xx means
// Postgres accepted the call, not that the rows the workflow built are the
// rows that landed.
//
// publish_report() returns its own count per table. This compares those
// against what was actually sent, and fails the run if they disagree. It is
// cheap, and it is the difference between "the database said OK" and "the
// report is there".
// ============================================================

const sent = $('Build Supabase Payloads').first().json;
const res = $input.first().json || {};

// PostgREST returns a scalar-returning function as the bare value, but some
// versions wrap it. Accept both rather than guessing.
const body = (res && typeof res === 'object' && res.ok === undefined && res.publish_report)
  ? res.publish_report
  : res;

if (body && body.error) {
  throw new Error(
    'publish_report was rejected by Postgres: ' +
    String(body.message || body.error) +
    (body.details ? ' — ' + body.details : '')
  );
}

if (!body || body.ok !== true) {
  throw new Error(
    'publish_report did not confirm success. Response was: ' +
    JSON.stringify(body).slice(0, 400)
  );
}

// The function counts rows it inserted; the payload counts rows it was
// given. report_insights is not in row_counts because it is always exactly
// one, so it is checked separately.
const expected = Object.assign({}, sent.row_counts, { report_insights: 1 });
const actual = body.rows || {};

const mismatches = [];
for (const table of Object.keys(expected)) {
  const want = Number(expected[table] || 0);
  const got = Number(actual[table]);
  if (!Number.isFinite(got)) {
    mismatches.push(table + ': Postgres reported no count');
  } else if (got !== want) {
    mismatches.push(table + ': sent ' + want + ', wrote ' + got);
  }
}

if (mismatches.length) {
  // Rolling back is not an option here — the transaction already committed.
  // Failing loudly is, and it puts the discrepancy in the execution log
  // where it can be read, rather than leaving a quietly wrong dashboard.
  throw new Error(
    'The report published but the row counts do not match what was sent:\n  ' +
    mismatches.join('\n  ') +
    '\nRun ' + sent.run_id + ' is on the dashboard and should be treated as suspect.'
  );
}

const total = Object.keys(actual).reduce(function (a, k) { return a + Number(actual[k] || 0); }, 0);

return [{
  json: {
    ok: true,
    run_id: body.run_id,
    publish_state: body.publish_state,
    rows_written: actual,
    total_rows: total,
    message: 'Published ' + body.run_id + ' — ' + total + ' rows across ' +
             Object.keys(actual).length + ' tables, in one transaction.',
  },
}];

// n8n Code node: Build Failure Record
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Build Failure Record                    (Run Once for ALL Items)
//
// Runs on the Error Trigger branch, and only there. It turns whatever n8n
// hands an error workflow into the one shape record_failed_run() accepts.
//
// This node lived inline in harness/build-workflow.py until the Supabase URL
// stopped being a literal. That made it the one Code node a reviewer could
// not read as JavaScript and the one body sync-remote.py could not push to
// the live export — which is exactly how the old hardcoded project ref
// survived in the deployed workflow after it had been removed everywhere
// else. Nine code nodes in code/ and a tenth hiding in the build script is
// not a rule, it is an exception waiting to be missed.
// ============================================================

// Records the failure AS A REPORT RUN, so a broken run is visible on the
// dashboard rather than only in n8n's execution log. A stale dashboard that
// looks healthy is worse than one that says it is stale.
const e = $input.first().json || {};
const ex = e.execution || {};
const err = ex.error || e.error || {};
const stamp = new Date().toISOString().slice(0, 10);
return [{
  json: {
    rows: [{
      run_id: 'run_failed_' + stamp,
      period_key: 'failed',
      period_label: 'Run failed',
      period_start: stamp,
      period_end: stamp,
      reference_date: stamp,
      run_status: 'failed',
      insight_source: 'none',
      confidence: 'low',
      grounded: false,
      failure_reason: String(err.message || 'Unknown error')
        + (ex.lastNodeExecuted ? ' (failed at: ' + ex.lastNodeExecuted + ')' : ''),
      requested_by: 'error_trigger',
      updated_at: new Date().toISOString(),
    }],
    // Which period this run was trying to refresh, when it got far enough to
    // know. record_failed_run() stamps last_failure_at/reason on THAT period's
    // published report so the dashboard can say 'this is stale, and here is
    // why' - without touching the report itself. null is a fine answer: a run
    // that died before resolving a period damaged nothing.
    affected_period_key: (function () {
      try { return $('Resolve Reporting Period').first().json.period_key || null; }
      catch (x) { return null; }
    })(),
    // Configuration only, no literal fallback. Read the same two ways
    // Resolve Reporting Period reads it — $vars first (n8n Cloud, the only
    // one available there), then $env (self-hosted, and BLOCKED on Cloud,
    // where touching it throws rather than returning undefined). Reading
    // only $env here would mean a failure on Cloud could not even record
    // itself. Prefer the value the run already resolved, when there is one:
    // then the failure record cannot disagree with the run it describes.
    supabase_url: (function () {
      try {
        const resolved = $('Resolve Reporting Period').first().json.supabase_url;
        if (resolved) return String(resolved).replace(/\/+$/, '');
      } catch (x) { /* died before the period was resolved */ }
      try {
        const v = (typeof $vars !== 'undefined' && $vars) ? $vars.IKE_SUPABASE_URL : undefined;
        if (v) return String(v).trim().replace(/\/+$/, '');
      } catch (x) { /* no Variables on this instance */ }
      try {
        const v = (typeof $env !== 'undefined' && $env) ? $env.IKE_SUPABASE_URL : undefined;
        if (v) return String(v).trim().replace(/\/+$/, '');
      } catch (x) { /* env access blocked — the Cloud default */ }
      return '';
    })(),
  },
}];

// n8n Code node: Build Discord Report
// Mode: RUN ONCE FOR ALL ITEMS

// ============================================================
// Build Discord Report                    (Run Once for ALL Items)
//
// Composes the whole published report as Discord markdown and emits it as
// ONE ITEM PER MESSAGE, so the Discord node downstream posts it in order.
//
// WHY IT SITS AFTER "Respond — Report Updated"
// --------------------------------------------
// The webhook caller is a browser waiting on a fetch. Discord is a third
// party that can be slow or down. Posting before responding would put a
// stranger's latency in front of the dashboard's spinner, and a Discord
// outage would read to the caller as a failed report - when the report was
// published, verified and is sitting on the dashboard already.
//
// WHY CHUNKS INSTEAD OF ONE MESSAGE
// ---------------------------------
// A Discord message body is capped at 2000 characters, and "a full report"
// is comfortably past that once the model has written three risks and three
// actions. Over the cap Discord rejects the whole POST with a 400 - it does
// not truncate for you - so the report would vanish exactly on the runs
// that had the most to say. This splits on line boundaries under a 1900
// character budget (leaving room for the part header), numbers the parts,
// and hard-caps the total so a pathological run cannot spam the channel.
//
// EVERY UPSTREAM READ IS DEFENSIVE
// --------------------------------
// This node is the last thing in the workflow and it is a NOTIFICATION. It
// must never be the reason a successful, published, verified run is marked
// failed. Anything it cannot read is reported inside the message as "not
// available" rather than thrown.
// ============================================================

const MAX_MESSAGE_CHARS = 1900;   // Discord's cap is 2000; the rest is headroom.
const MAX_MESSAGES = 6;           // ~11k characters. Past this, link out instead.

function pull(nodeName) {
  try { return $(nodeName).first().json || {}; } catch (e) { return {}; }
}

const metrics = pull('Compute Metrics');
const parsed = pull('Parse & Validate Insights');
const payloads = pull('Build Supabase Payloads');
const verify = $input.first() ? ($input.first().json || {}) : {};
const published = verify.ok === true ? verify : pull('Verify Publish');

const period = metrics.period || {};
const insights = parsed.insights || {};

// ---- formatting ---------------------------------------------
// Deliberately the same conventions as the dashboard and the model prompt:
// no currency symbol anywhere, rates as one-decimal percentages, durations
// in days. Three renderings of one number is how a report starts
// contradicting itself.
function num(n) {
  if (n === null || n === undefined || !Number.isFinite(Number(n))) return 'not available';
  return Number(n).toLocaleString('en-GB', { maximumFractionDigits: 2 });
}
function pct(n) {
  if (n === null || n === undefined || !Number.isFinite(Number(n))) return 'not available';
  return (Number(n) * 100).toFixed(1) + '%';
}
function days(n) {
  if (n === null || n === undefined || !Number.isFinite(Number(n))) return 'not available';
  return Number(n).toFixed(1) + ' d';
}
function fmt(key, n) {
  if (/_rate$/.test(key)) return pct(n);
  if (/_days$/.test(key)) return days(n);
  return num(n);
}
// The prompt insists on one capitalisation for department names, so the
// prose and the labels around it must not disagree. Anything not in the map
// falls back to sentence case.
const LABELS = {
  sales: 'Sales',
  marketing: 'Marketing',
  project_delivery: 'Project Delivery',
  people_ops: 'People Ops',
  cross_functional: 'Cross-functional',
  period: 'Reporting period',
};
function title(key) {
  if (LABELS[key]) return LABELS[key];
  // The unit is already in the value, so "Average delay: 6.5 d" beats
  // "Average delay days: 6.5 d". `_rate` stays: "Win rate" reads correctly.
  return String(key).replace(/_days$/, '').replace(/_/g, ' ')
    .replace(/^./, function (c) { return c.toUpperCase(); });
}

// Discord renders _italics_ and **bold** but has no tables, so the movement
// note goes inline. `not_comparable` prints nothing at all rather than a
// dash the reader has to decode.
function movement(key, t) {
  if (!t || t.direction === 'not_comparable') return '';
  if (t.direction === 'flat') return '  (unchanged)';
  if (t.direction === 'stable') return '  (broadly flat)';
  const arrow = t.direction === 'up' ? '▲' : '▼';
  const abs = /_rate$/.test(key)
    ? Math.abs(Number(t.change) * 100).toFixed(1) + ' pts'
    : num(Math.abs(Number(t.change)));
  const rel = (t.percent_change === null || t.percent_change === undefined)
    ? ''
    : ', ' + (Number(t.percent_change) * 100).toFixed(1) + '%';
  return '  (' + arrow + ' ' + abs + rel + ')';
}

const SEVERITY = { high: '🔴', medium: '🟠', low: '🟡' };
const DQ = { error: '⛔', warning: '⚠️', info: 'ℹ️' };

// ---- header --------------------------------------------------
// The three values Compute Metrics actually produces. A run missing one
// source is still published — a partial report beats no report — so
// `partial` is a warning, not a failure.
const runStatus = String(metrics.run_status || 'unknown');
const STATUS_ICON = { succeeded: '✅', partial: '⚠️', failed: '⛔' };
const statusIcon = STATUS_ICON[runStatus] || '❔';
const source = parsed.insight_source === 'claude'
  ? ('Claude' + (parsed.model ? ' (' + parsed.model + ')' : '') + (parsed.grounded ? ', grounded' : ', UNVERIFIED FIGURES'))
  : 'deterministic fallback — the model call did not succeed';

const dq = metrics.data_quality_summary || {};
const rows = published.rows_written || payloads.row_counts || {};
const totalRows = Object.keys(rows).reduce(function (a, k) { return a + Number(rows[k] || 0); }, 0);

const lines = [];
lines.push('**KOYA TALENT — OPERATIONS REPORT**');
lines.push(period.label || 'Reporting period not available');
lines.push('`' + (period.start || '?') + '` → `' + (period.end || '?') + '`'
  + (period.days ? '  ·  ' + period.days + ' days' : '')
  + (period.compare_label ? '  ·  compared with ' + period.compare_label : ''));
lines.push('');
lines.push(statusIcon + '  Run status **' + runStatus + '**  ·  Confidence **'
  + String(insights.confidence || 'unknown') + '**');
lines.push('Insights: ' + source);
lines.push('Data quality: ' + (dq.errors || 0) + ' errors, ' + (dq.warnings || 0) + ' warnings'
  + (dq.affected_sources && dq.affected_sources.length ? ' (' + dq.affected_sources.join(', ') + ')' : ''));
lines.push('Published: ' + totalRows + ' rows across ' + Object.keys(rows).length + ' tables  ·  run `'
  + String(metrics.run_id || 'unknown') + '`');

// Every figure below was produced by code, not by the model. When the model
// call failed the prose is deterministic and says so above — but the numbers
// are identical either way, and that is worth the reader knowing.
if (parsed.insight_source !== 'claude') {
  lines.push('');
  lines.push('> The commentary below was generated deterministically because the model call did not succeed. Every figure is unaffected.');
} else if (parsed.grounded === false) {
  lines.push('');
  lines.push('> Some figures in the commentary could not be matched against the calculated metrics: '
    + (parsed.unverified_figures || []).slice(0, 8).join(', ') + '. Treat the prose with care; the figures below are authoritative.');
}

// ---- executive summary ---------------------------------------
lines.push('');
lines.push('__**Executive summary**__');
lines.push(String(insights.executive_summary || 'No summary was produced for this run.'));

// ---- the numbers ---------------------------------------------
// Driven off the metrics object itself rather than a hardcoded list, so a
// metric added upstream appears here without this node being edited — the
// alternative is a report that quietly stops mentioning a new KPI.
const DOMAINS = [
  ['sales', 'Sales and marketing'],
  ['delivery', 'Project Delivery'],
  ['people_ops', 'People Ops'],
];

for (const pair of DOMAINS) {
  const key = pair[0];
  const domain = (metrics.metrics || {})[key];
  if (!domain) continue;
  const trend = (metrics.trends || {})[key] || {};

  lines.push('');
  lines.push('__**' + pair[1] + '**__');

  for (const metricKey of Object.keys(domain)) {
    if (metricKey.charAt(0) === '_') continue;          // _coverage and friends
    const node = domain[metricKey];
    if (!node || typeof node !== 'object') continue;
    if (Array.isArray(node.value)) continue;            // breakdowns, handled below
    if (node.value !== null && typeof node.value === 'object') continue;

    if (node.value === null) {
      // A missing number is reported WITH ITS REASON. "not available" on its
      // own invites the reader to assume zero, which is the one reading the
      // whole pipeline is built to prevent.
      lines.push('• ' + title(metricKey) + ': not available — ' + String(node.unavailable_reason || 'no reason recorded'));
    } else {
      lines.push('• ' + title(metricKey) + ': **' + fmt(metricKey, node.value) + '**' + movement(metricKey, trend[metricKey]));
    }
  }
}

// ---- risks ----------------------------------------------------
const risks = Array.isArray(insights.risks_and_anomalies) ? insights.risks_and_anomalies : [];
lines.push('');
lines.push('__**Risks and anomalies**__');
if (!risks.length) {
  lines.push('None worth raising this period.');
} else {
  for (const r of risks) {
    lines.push((SEVERITY[r.severity] || '🟡') + ' **' + title(String(r.area || 'cross functional')) + '** — ' + String(r.finding || ''));
    if (r.evidence) lines.push('_' + String(r.evidence) + '_');
  }
}

// ---- actions --------------------------------------------------
const actions = Array.isArray(insights.recommended_actions) ? insights.recommended_actions : [];
lines.push('');
lines.push('__**Recommended actions**__');
if (!actions.length) {
  lines.push('None warranted this period.');
} else {
  let i = 0;
  for (const a of actions) {
    i += 1;
    lines.push(i + '. ' + (SEVERITY[a.priority] || '🟡') + ' **' + title(String(a.area || 'cross functional')) + '** — ' + String(a.action || ''));
    if (a.rationale) lines.push('_' + String(a.rationale) + '_');
  }
}

// ---- data quality ---------------------------------------------
// The model's wording, not the raw diagnostics: 40 identical field-level
// warnings belong on the dashboard, not in a channel people have to read.
const dqWarnings = Array.isArray(insights.data_quality_warnings) ? insights.data_quality_warnings : [];
lines.push('');
lines.push('__**Data quality**__');
if (!dqWarnings.length) {
  lines.push('Nothing affecting the conclusions above.');
} else {
  for (const w of dqWarnings) {
    lines.push('⚠️ **' + title(String(w.source || 'source')) + '** — ' + String(w.issue || ''));
    if (w.impact) lines.push('→ ' + String(w.impact));
  }
}

// A config error is a DEPLOYMENT problem, kept out of data quality upstream
// so it cannot downgrade the report's confidence. It still has to reach a
// human, and this is the message a human actually reads.
const configErrors = Array.isArray(metrics.config_errors) ? metrics.config_errors : [];
if (configErrors.length) {
  lines.push('');
  lines.push('__**Configuration**__');
  for (const c of configErrors) lines.push('⛔ ' + String(c.message || c.code));
}

lines.push('');
lines.push('_Koya Talent AI Operations Reporting · n8n · ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC_');

// ---- chunk ----------------------------------------------------
// Split on line boundaries so a bullet is never cut mid-word. A single line
// longer than the budget (a very long executive summary) is hard-split, and
// that is the only place a word can break.
const chunks = [];
let buf = '';
function flush() { if (buf.length) { chunks.push(buf); buf = ''; } }

// A section heading stranded at the bottom of a message, with its content in
// the next one, reads as a report that lost something. So a heading is
// measured together with the line under it and they move as a pair.
function isHeading(line) { return /^__\*\*.*\*\*__$/.test(line); }

for (let i = 0; i < lines.length; i += 1) {
  let line = lines[i];
  const glue = (isHeading(line) && lines[i + 1] !== undefined) ? lines[i + 1].length + 1 : 0;

  while (line.length > MAX_MESSAGE_CHARS) {
    flush();
    chunks.push(line.slice(0, MAX_MESSAGE_CHARS));
    line = line.slice(MAX_MESSAGE_CHARS);
  }
  if (buf.length + line.length + 1 + glue > MAX_MESSAGE_CHARS) flush();
  buf += (buf.length ? '\n' : '') + line;
}
flush();

let truncated = false;
if (chunks.length > MAX_MESSAGES) {
  truncated = true;
  chunks.length = MAX_MESSAGES;
  chunks[MAX_MESSAGES - 1] += '\n\n_…report truncated at ' + MAX_MESSAGES + ' messages. The full report is on the dashboard._';
}

// One item per message. The Discord node runs once per item and n8n keeps
// item order, so parts arrive in sequence.
return chunks.map(function (raw, idx) {
  // A blank line left at a split point renders as dead space at the top or
  // bottom of a Discord message.
  const content = raw.replace(/^\n+/, '').replace(/\n+$/, '');
  const header = chunks.length > 1 ? '`(' + (idx + 1) + '/' + chunks.length + ')`\n' : '';
  return {
    json: {
      content: header + content,
      part: idx + 1,
      parts: chunks.length,
      truncated: truncated,
      run_id: metrics.run_id || null,
      period_key: period.key || null,
      run_status: runStatus,
    },
  };
});
